programs.sol:
"""Approximate a spelling feature for CT and related consonant clusters.

Short, unfinished CT fragments respond most strongly. Familiar Latin-derived
stems keep weaker responses in longer words; active/actual and control-code
abbreviations are exceptions. PT/KT spellings and world, holy-title, milk and
ratio vocabulary give smaller positive responses. Results/analysis vocabulary
is negative. This is token-local: contextual modulation and many weak lexical
responses are deliberately omitted.
"""
import math

READS = ()
# Bare versus continued stems. Comments identify the familiar word families.
CT_STEMS = {
    'rect': (3.1, 1.0),      # straight: rectangle
    'sect': (1.55, 0.7),     # cut: section
    'fact': (1.1, 0.75),     # make: fact, factor, factory
    'dict': (1.45, 0.65),    # say: dictionary
    'lect': (1.65, 0.75),    # read: lecture
    'fract': (1.95, 0.8),    # break: fraction
    'lact': (2.25, 0.7),     # milk: lactation
    'spect': (1.05, 0.55),   # look: spectrum
    'react': (1.05, 0.5),    # reacting
    'tract': (1.3, 0.5),     # pull: traction
    'oct': (2.25, 0.65),     # eight: octave, October
    'punct': (1.55, 0.4),    # point: puncture
    'ract': (2.8, 1.0),      # fragment of fract-/tract-
    'unct': (2.4, 0.9),      # fragment of conjunct-/junct-
    'sanct': (2.0, 0.4),     # holy: sanctuary
}
WORLD_WORDS = {'world', '世界', '世'}
HOLY_WORDS = {'saint', 'christ', '聖', '圣'}
MILK_WORDS = {'乳', 'breastfeeding'}
ACT_INFLECTIONS = {'': 1.0, 's': 0.7, 'ed': 0.8, 'ing': 0.6}


def ct_response(token, clean, word):
    before, after = word.split('ct', 1)
    if word.startswith(('ctx', 'ctrl', 'ctl', 'ctr')):
        return 0.15
    if word.startswith('act'):
        base = 1.65 if token.startswith(' ') or clean[0].isupper() else 2.55
        if clean.isupper():
            base = 2.0
        factor = ACT_INFLECTIONS.get(after)
        if factor is None:
            factor = 0.35 if after.startswith('ion') else 0.5
        return 0.05 if after.startswith(('iv', 'ual', 'ly')) else base * factor
    if word.startswith('duct'):
        base = 2.4 if token.startswith(' ') else 0.9
        return base * math.exp(-0.55 * len(after))
    if word.startswith('ectomy'):  # surgical-removal suffix
        return 1.85
    if word.startswith('perfect'):
        return 0.7 if word == 'perfect' else 0.18
    if word.startswith('aspect'):
        return 0.52
    if word.startswith('exact'):
        return 0.73 if word == 'exact' else 0.01
    if word.startswith(('structur', 'effect')):
        return -0.13
    stem = before + 'ct'
    if stem in CT_STEMS:
        value = CT_STEMS[stem][bool(after)]
        if stem == 'tract' and not token.startswith(' '):
            value *= 0.3
        if stem == 'dict' and token.startswith('_'):
            value *= 0.4
        if stem == 'lect' and word.startswith('lection'):
            value = 0.0
        return value
    base = (4.2, 2.6, 1.0)[min(len(before), 2)] if len(before) <= 2 else 0.05
    if not before and clean.startswith('Ct'):
        base = 1.5
    if before == 'u':
        base = 3.2
    return base * math.exp(-0.5 * len(after))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    clean = token.strip(' \t\n_./\\()-')
    word = clean.lower()
    value = -0.001
    if 'ct' in word:
        value = ct_response(token, clean, word)
    elif any(c in word for c in ('pt', 'kt', 'кт')):
        cluster = next(c for c in ('pt', 'kt', 'кт') if c in word)
        before, after = word.split(cluster, 1)
        base = 0.9 if len(before) <= 1 else 0.05
        if cluster != 'pt' and len(before) <= 2:
            base = 0.9
        if cluster == 'pt' and after.startswith('r'):
            base = 0.05
        if before in ('se', 'asym'):
            base = 1.0
        value = base * math.exp(-0.5 * len(after))
    elif word in ('クト', 'ク'):
        value = 1.7 if word == 'クト' else 0.5
    elif word in WORLD_WORDS:
        value = 0.8
    elif word in HOLY_WORDS:
        value = 0.6
    elif word in MILK_WORDS:
        value = 0.65
    elif word in ('ratio', 'ratios', 'rational', 'rationality'):
        value = 0.65
    elif word == 'results':
        value = -0.33
    elif word in ('analysis', 'analyses'):
        value = -0.2
    return None, float(value)

programs.haiku:
"""Partitive 'of' detector (one rank-one piece of layer-0 down_proj).

The component responds to the word " of" according to the word before it:
  * after a quantifier that picks out some of a group ("none of", "each of", "some of",
    "most of", "one of", "the rest of", "a lot of", "majority of"): strongly negative;
  * after a part/measure noun ("part of", "piece of", "value of", "side of", "set of",
    "type of"): moderately negative;
  * after a few abstract or technical nouns ("case of", "sum of", "concept of",
    "ratio of", "form of"): positive;
  * other " of" (e.g. "University of", "country of"): near zero.
It also goes negative on the chat template's "</think>" and on determiner/quantifier
words such as 该 and 多くの, and mildly positive on the genitive particles 的 and の.
Everything else is predicted as 0.
"""

READS = ()

QUANTIFIERS = {
    "none", "each", "every", "some", "most", "any", "many", "one", "all", "both",
    "rest", "lot", "lots", "half", "majority", "those", "which", "few", "several",
    "two", "three", "four", "group", "couple", "bunch", "handful", "percent", "%",
    "much", "plenty", "thousands", "these",
}
PART_NOUNS = {
    "part", "parts", "piece", "portion", "set", "value", "values", "side", "size",
    "type", "types", "quality", "position", "collection", "impact", "speed", "velocity",
    "performance", "results", "power", "treatment", "bottom", "range", "members",
    "member", "amount", "level", "levels", "kind", "series", "variety", "bit",
}
ABSTRACT_NOUNS = {
    "case", "sum", "concept", "matter", "issue", "form", "method", "process",
    "definition", "principles", "basis", "source", "problem", "equation", "topic",
    "provision", "doctrine", "factors", "ratio", "date",
}
QUANTITY_WORDS = {"该", "多くの", "很多", "许多", "不少", "多数", "ほとんど"}
GENITIVE_PARTICLES = {"的", "の"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "</think>":
        return carry, -0.6
    if token in QUANTITY_WORDS:
        return carry, -0.7
    if token in GENITIVE_PARTICLES:
        return carry, 0.12
    if token != " of" or len(prefix.token_ids) < 2:
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.05
    head = prefix.token_strings[-2].strip().lower()
    if head in QUANTIFIERS:
        return carry, -0.9
    if head in PART_NOUNS:
        return carry, -0.3
    if head in ABSTRACT_NOUNS:
        return carry, 0.25
    return carry, -0.05

programs.sol:
"""Lexical cues for means, attribution, and accordance, plus the 'press' sense.

The strongest cues are Chinese 按/按照 ('according to', also 'press'), English
'by', and 'according to'. Match these spellings in code as well as prose.
Phrase endings such as 'based on' are recognized with one previous-token state.
A separate negative response covers thin spaces (U+2009). Unlisted tokens
receive zero; these rules do not attempt to reproduce every lexical fluctuation.
The values are activation averages fitted on training text, not probabilities.
"""
READS = ()

# Chinese cues for acting by a means, following a rule, or citing a source.
CHINESE_CUES = {
    '按': 8.6, '按照': 6.65, '按规定': 3.1,
    '依': 3.1, '依据': 2.2, '依據': 2.2, '依法': 0.85,
    '照': 1.95, '据': 2.05, '據': 1.4, '根据': 2.2, '根據': 1.95,
    '以': 1.3, '是以': 1.1, '从': 1.0, '從': 1.0,
    '通过': 0.83, '通過': 0.65, '透过': 0.65, '透過': 0.65,
    '由': 0.55, '用': 0.4, '经': 0.4, '經': 0.4,
    '凭': 1.1, '憑': 1.1, '凭借': 0.7, '采用': 0.77,
    '遵循': 1.0, '循': 1.0, '本着': 1.4,
    '参照': 1.7, '依照': 3.75, '沿': 1.7, '沿着': 2.3,
    '按下': 3.0, '按键': 1.15, '按摩': 1.17, '摁': 3.9,
}

# Other translations of 'by', 'according to', 'in accordance', and 'per'.
OTHER_CUES = {
    'по': 0.96, 'соответствии': 0.8,
    'selon': 1.3, 'según': 1.0, 'secondo': 0.75,
    'acordo': 0.65, 'acuerdo': 0.65,
    'par': 0.12, 'por': 0.13, 'gemäß': 0.35, 'göre': 0.4,
    'ตาม': 1.6, 'によって': 0.65, 'により': 0.4, 'に基づ': 0.58,
}


ACCORDANCE_WORDS = {
    'according': 1.38, 'ccording': 1.38, 'accordance': 0.94,
    'accordingly': 0.47, 'accord': 0.4,
}
PHRASE_ENDINGS = {
    'according to': 1.72, 'based on': 0.98, 'based upon': 0.51,
    'pursuant to': 0.32, 'accordance with': 0.53,
}
DEFINITION_WORDS = {
    'given', 'defined', 'described', 'calculated', 'explained',
    'designed', 'proposed', 'specified', 'prescribed',
}
LOW_BY_CONTEXTS = {
    'affected', 'surrounded', 'accompanied', 'occupied',
    'replaced', 'struck', 'preceded',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = ACCORDANCE_WORDS.get(
        lower, CHINESE_CUES.get(word, OTHER_CUES.get(lower, 0.0))
    )
    if len(word) > 2:
        if word.endswith('按照'):
            value = 6.2
        elif word.endswith('根据'):
            value = 1.7
        elif word.endswith('通过'):
            value = 0.85
    boundary_word = word.lstrip('/_-.')
    if boundary_word.lower() == 'by':
        if boundary_word == 'By':
            value = 0.85
        elif boundary_word == 'BY':
            value = 0.5
        else:
            value = 0.55
        if previous == 'followed':
            value = -0.17
        elif previous in {'divided', 'multiplied'}:
            value = 0.0
        elif previous in LOW_BY_CONTEXTS:
            value = 0.1
        elif previous in DEFINITION_WORDS:
            value = 0.9
    elif (boundary_word.startswith('By') and len(boundary_word) > 2
          and boundary_word[2].isupper()):
        value = 0.65
    elif boundary_word.endswith('By'):
        value = 0.5
    elif lower == 'per' and token.startswith(' '):
        value = 0.22
    elif lower in {'press', 'pressed', 'pressing', 'presses'}:
        if lower in {'pressed', 'presses'}:
            value = 0.83
        elif lower == 'pressing':
            value = 1.1
        else:
            value = 1.7 if token.startswith(' ') or word == 'Press' else 0.8
    value = PHRASE_ENDINGS.get(previous + ' ' + lower, value)
    if '\ufffd' in word:
        # A byte-fragment token may finish a Chinese character.
        final_character = prefix.text_prefixes[-1][-1:]
        if final_character in CHINESE_CUES:
            value = CHINESE_CUES[final_character]
            if final_character == '按':
                value = 9.8
        elif final_character == '\u2009':
            value = -1.08
    elif token == '\u2009':
        value = -1.08
    previous_word = 'according' if lower == 'ccording' else lower
    return (doc, previous_word), float(value)

programs.haiku:
"""Activation of layers.0.mlp.down_proj:2243: a "according to / on the basis of / by means of"
detector.

What it does: the component writes a strong push into the residual stream on the word that
introduces the standard, source or means of an action. The strongest cases are Chinese
prepositions of that meaning, led by 按 (the start of 按照 "according to"; also "press"), then
按照, 依照, 依, 依据, 根据, 据, 照. Weaker and English cases: "according" and "to" in
"according to", "based on", "by" (passive agent or means), "per", "in accordance with",
"press" (keyboard sense), and Russian "по" meaning "by / according to". Everything else
predicts 0. Values are the typical activation of each word, read off training-data activations.
"""

READS = ()

# Chinese words for 'according to / on the basis of / by means of' (and 按 'press').
CHINESE = {
    "按": 8.6, "按照": 6.5, "依照": 3.8, "依": 3.1, "按下": 3.0, "依据": 2.3,
    "根据": 2.1, "据": 2.0, "照": 2.5, "以": 1.4, "从": 1.1, "從": 1.0,
    "依法": 0.9, "通过": 0.8, "采用": 0.8, "由": 0.6, "每": 0.55, "用": 0.4,
}
ACCORDING = {" according", " According", "According", "according"}
BY_LOWER = {" by", "by"}
BY_UPPER = {" By", "By", " BY"}
PRESS = {" press", " Press", "Press", "press"}


def step(carry, prefix, upstream):
    """The activation at the newest token, from that token and the one before it (same document)."""
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok in CHINESE:
        value = CHINESE[tok]
    elif tok in ACCORDING:
        value = 1.4
    elif tok == " to" and prev in ACCORDING:
        value = 1.7
    elif tok == " accordance":
        value = 0.9
    elif tok == " on" and prev in {" based", "based"}:
        value = 1.0
    elif tok in BY_LOWER:
        value = 0.0 if prev in {" followed", " divided", " multiplied"} else 0.55
    elif tok in BY_UPPER:
        value = 0.85
    elif tok in PRESS:
        value = 1.7
    elif tok == " по" or tok == "по":
        value = 0.95
    elif tok == " per":
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Surface detector for multilingual infinitive-like verb endings.

Russian endings give large positive values. Romance endings are gated by
recent function words: the same letters in English words or names usually
have much smaller values. Distinctive longer endings need less context.
Common complete infinitives, a few Japanese/Polish endings, and chat/tool
boundary markers are handled separately. No grammatical parse is attempted.
"""
READS = ()

# Non-Romance, Spanish/Portuguese, French, Italian language cues.
CUES = (
    set('the and of to in that is with for on this it as was be by are '
        'from at or have not but an which you their will der die das und '
        'den dem ein eine zu nicht mit von für ist auch het van een dat '
        'niet op zijn dan maar jeg og det ikke av och bir ve bu için'.split()),
    set('el los las y una por para como con se lo su es sus del más '
        'não do da dos das os em com uma ao são você de la en que un'.split()),
    set('le les du des une et pour dans est pas au aux ce sur avec '
        'mais qui ses sont plus de la en que un'.split()),
    set('di il gli che per della dello delle degli non è sono '
        'si nel nella sul alla anche questo la un'.split()),
)

INFINITIVES = set('''
faire avoir voir prendre rendre mettre donner trouver parler choisir
venir devenir savoir partir tenir hacer seguir usar mejorar contar tomar
pensar llevar trabajar entrar mostrar volver conocer pagar conectar
compartir encontrar crear criar saber estar tener haber mantener poner
obtener realizar evitar dejar buscar cambiar recibir verificar mover
perder responder comprar llegar salir imprimir aprender continuar
utilizar calcular guardar fare avere andare vedere trovare fazer
eliminar agregar decir conseguir entender resolver iniciar sentir abrir
modificar registrar enviar comenzar jugar comer generar
'''.split())
WEAKER_INFINITIVES = set('être aller ser poder essere dire dare dar ver ir'.split())

# Columns are: other languages, Spanish/Portuguese, French, Italian.
ENDING_VALUES = {
    'oir': (.6, 1.8, 1.9, 1.3),
    'ar': (.4, 3.4, 1.0, 1.8),
    'ir': (.3, 3.2, 1.9, 1.6),
    'er': (.1, 1.2, 1.2, .8),
    'are': (.3, 1.3, .8, 2.0),
    'ere': (.1, .7, .4, 1.35),
    'ire': (.1, .9, .8, 2.1),
    're': (0.0, .5, .2, .4),
}
RUSSIAN_ENDINGS = (
    ('иться', 2.6), ('аться', 2.3), ('ивать', 3.3), ('ывать', 2.75),
    ('овать', 2.9), ('нуть', 2.75), ('ить', 3.5), ('ать', 3.0),
    ('еть', 2.7), ('ять', 2.3), ('ыть', 2.7), ('уть', 1.1), ('ести', 2.0),
)
NONVERBS = set('пять опять девять десять память треть путь печать '
               'кровать благодать'.split())


CHAT_MARKERS = {'<tool_response>': .82, '<|im_start|>': -.09}
SLAVIC_FORMS = {
    'ть': 1.7, 'ь': .35, 'ć': 1.3, 'ť': .8, 'стать': 1.5, 'найти': 3.1,
}
JAPANESE_RU_ENDINGS = {'る', 'える', 'ける', 'める', 'れる', 'になる'}
JAPANESE_OTHER_ENDINGS = {'する', 'む', 'く', 'す'}
LONG_ENDINGS = (
    (3.8, ('izar', 'ificar', 'ecer', 'uir', 'strar', 'piar')),
    (2.1, ('crire', 'érer', 'iquer', 'indre', 'ître', 'trer')),
    (2.3, ('izzare', 'icare', 'iare', 'edere', 'arse', 'irse')),
)


def response(token, language):
    word = token.strip()
    if token in CHAT_MARKERS:
        return CHAT_MARKERS[token]
    if word in SLAVIC_FORMS:
        return SLAVIC_FORMS[word]
    if word not in NONVERBS:
        for ending, value in RUSSIAN_ENDINGS:
            if word.endswith(ending):
                return value
    if word in JAPANESE_RU_ENDINGS:
        return 1.1
    if word in JAPANESE_OTHER_ENDINGS:
        return .65
    if word.endswith('ć'):
        return .5 if word.endswith('ść') else 2.1
    if token[:1].isspace():
        if word == 'hacer':
            return 4.7
        if word in INFINITIVES:
            return (2.2, 3.2, 2.3, 2.3)[language]
        if word in WEAKER_INFINITIVES:
            return (.3, 1.2, 1.4, 1.1)[language]
        return .54 if word == 'far' else 0.0
    if word.isalpha() and word.islower() and 2 <= len(word) <= 6:
        if word == 'rir':
            return 5.3
        if word == 'arsi':
            return 1.35
        if word in {'ando', 'iendo', 'endo'}:
            return .4
        for value, endings in LONG_ENDINGS:
            if word.endswith(endings):
                return value
        for ending, values in ENDING_VALUES.items():
            if word.endswith(ending):
                return values[language]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    scores = [0.0] * 4 if carry is None or carry[0] != doc else [
        x * .98 for x in carry[1]
    ]
    if token[:1].isspace() or prefix.position == 0:
        word = token.strip().lower()
        for i, words in enumerate(CUES):
            scores[i] += float(word in words)
    language = max(range(4), key=lambda i: scores[i])
    if scores[language] < 1.5:
        language = 0
    return (doc, scores), response(token, language)

programs.luna:
"""Predict small boosts on verb-like word pieces and two chat markers."""
READS: tuple[str, ...] = ()

# Common Romance endings and infinitive pieces.
ROMANCE_ENDINGS = (
    "ando", "iendo", "endo", "ar", "er", "ir", "are", "ere",
    "ire", "erà", "irà", "uire", "izzare", "icare", "trer",
    "venir", "faire", "dire", "verter", "ier",
)
SLAVIC_ENDINGS = (
    "ать", "ить", "еть", "овать", "ести", "ти", "уть", "ывать",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<tool_response>":
        return None, 0.84
    if token == "user":
        return None, 0.34
    if token[:1].isspace():
        return None, 0.0

    piece = token.strip().lower()
    if piece.endswith(ROMANCE_ENDINGS + SLAVIC_ENDINGS):
        return None, 0.4
    return None, 0.0

programs.sol:
"""Approximate a lexical SE-family feature, rather than one shared meaning.

The strongest response is to the short fragment se, especially capitalized.
Longer se- words have weaker, root-dependent responses; section, seal and
seed remain strong, while self, second, service and search are weak.
There are also explicit se syllables in other scripts, the section sign,
and a few translated relatives. Unlisted, unrelated tokens predict zero.

The preceding token and predicted strength are carried. This distinguishes
word-internal se, allows a small continuation, and recognizes makes sense and
section of. State resets at document boundaries. These are coarse lexical
rules, not an attempt to capture every small token-specific activation.
"""

READS = ()

# Spelling families: inflections inherit their root's response.
FAMILIES = (
    ('section', 2.5), ('securiti', 2.8), ('secur', 1.15),
    ('seal', 3.0),
    ('seed', 2.3), ('seat', 2.05), ('seattle', 0.5),
    ('several', 0.0), ('sever', 1.8), ('seven', 0.05),
    ('sew', 2.3), ('seem', 1.4), ('seek', 1.4),
    ('seas', 1.0), ('sear', 0.1), ('secondary', 1.3),
    ('second', 0.1), ('secret', 0.85), ('sect', 1.3),
    ('segment', 1.35), ('self', 0.0), ('selbst', 0.0),
    ('semi', 1.7), ('semen', 3.0), ('senior', 1.0),
    ('senat', 1.25), ('sens', 0.3), ('send', 0.3),
    ('sent', 0.3), ('separ', 0.9), ('series', 0.85),
    ('server', 0.8), ('servic', 0.05), ('serv', 0.25),
    ('setup', 0.0), ('settle', 0.05), ('sex', 1.1),
)


# Familiar se-family words in Chinese, and irregular English inflections.
RELATED_WORDS = {
    '封': 2.9, '密封': 3.8,                 # seal
    '座': 0.8, '坐': 0.75, '座位': 1.4,   # seat
    '种': 0.9, '種': 0.8, '种子': 2.6,    # seed
    '严重': 1.6, '严重的': 1.3,             # severe
    '似乎': 1.9, '性感': 1.3,              # seem; sexy
    '安全': 0.55, '秘密': 1.0, '秘': 1.0,  # secure; secret
    '段': 0.8, '系列': 0.75, '序列': 0.9,               # section; series
    '证券': 2.8, '服务器': 0.7, '季节': 1.0, # securities; server; season
    '塞': 2.1,                             # Chinese se syllable
    'saw': 0.5, 'sought': 0.85,            # see; seek
    'ese': 0.95, 'ose': 0.6, 'ense': 0.45, # short -se endings
}
FAMILIES = tuple(sorted(FAMILIES, key=lambda item: -len(item[0])))


def spelling_value(token):
    text = token.strip()
    if '§' in text:
        return 2.2
    if text == 'セ':
        return 3.7
    if text in ('せ', '세'):
        return 1.6
    if text.startswith(('セ', 'せ', '세')):
        return 0.7
    if text.lower().startswith('се'):
        if len(text) == 3:
            return {'к': 2.4, 'м': 1.9, 'р': 1.1,
                    'т': 0.95, 'н': 1.1}.get(text[-1].lower(), 1.0)
        return 0.5
    word = text.lstrip('._-/([{\'"')
    low = word.lower()
    if low in RELATED_WORDS:
        return RELATED_WORDS[low]
    if low == 'sé':
        return 1.1
    if not low.startswith('se'):
        return 0.0
    if low == 'se':
        if word == 'Se':
            return 4.5
        if word == 'SE':
            return 3.3
        return 2.75 if token[:1].isspace() else 3.9
    if low in ('sect', 'sequ', 'separ', 'serv'):
        return {'sect': 2.0, 'sequ': 1.3,
                'separ': 2.0, 'serv': 0.6}[low]
    if len(low) == 3:
        # The third letter differentiates short syllable fragments.
        return {'a': 1.2, 'c': 2.2, 'd': 1.5, 'e': 0.9,
                'g': 1.9, 'l': 0.9, 'm': 2.0, 'n': 1.0,
                'p': 1.7, 'q': 1.5, 'r': 1.0, 's': 0.65,
                't': 0.75, 'u': 0.35, 'w': 2.3, 'x': 1.1
                }.get(low[2], 1.4)
    for root, value in FAMILIES:
        if low.startswith(root):
            return value
    return 0.6


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    previous_value = 0.0 if reset else carry[2]
    value = spelling_value(token)
    word = token.strip().lstrip('._-/([{\'"')
    low = word.lower()
    inside_word = (previous and previous[-1].isalpha() and ord(previous[-1]) < 256
                   and token[:1].isalpha())
    if low == 'se' and reset:
        if word == 'Se':
            value = 7.0
        else:
            value = 3.75 if token[:1].isspace() else 4.65
    elif low == 'se' and word == 'se' and inside_word:
        last = previous[-1].lower()
        if last in 'uy':
            value = 1.0
        else:
            value = 1.4 if last in 'ersé' else 2.2
    elif low == 'se' and word == 'SE' and inside_word:
        value = 2.05
    elif low == 'sed' and inside_word:
        value = 0.0 if word.isupper() else 0.4
    elif low.startswith('se') and low != 'se':
        if word[:1].isupper():
            value += 0.4 if low in ('sect', 'sequ') else 0.12
        if inside_word:
            value *= 0.8
            if low.startswith('sect') and previous.lower().endswith('inter'):
                value *= 0.3
    # A split se-syllable continues weakly into the next alphabetic piece.
    if previous.strip().lower() == 'se' and token[:1].isalpha():
        value += 0.1 * previous_value
    if low == 'sense':
        value = 0.0 if previous.strip().lower() in ('make', 'makes') else 0.6
    if token == ' of' and previous.strip().lower() in ('section', 'sections'):
        value = 0.4
    return (doc, token, value), float(value)

"""A short-range response to attributive/possessive linkers.

The next token after Chinese 的 or Japanese の gets a positive pulse,
stronger for short grammatical tokens and weaker for long words or sentence
ends. A linker inside the previous token gives a weaker delayed pulse.
Fused 的 and tokens containing の get negative offsets; を gets +0.15.
Related Chinese particles and Japanese inflectional endings give smaller
pulses. Memory resets between documents. Lexical variation is not modeled.
"""
READS = ()

PRONOUNS = ('我', '你', '他', '她', '它', '您', '咱', '自己')
DETERMINERS = ('这', '那', '這', '哪', '此', '该', '該')
QUANTIFIERS = (
    '一', '每', '各', '所有', '任何', '几', '幾', '多', '少', '两', '兩',
)
FUNCTION_WORDS = set(
    '有 是 不 没 沒 无 無 在 从 從 到 来 來 去 由 与 與 和 及 而 但 '
    '也 又 都 就 才 还 還 更 很 最 太 将 將 会 會 能 可以 可 要 应 應 '
    '为 為 把 被 给 給 所 着 著 了 得 地 之 还是 還是'.split()
)
JAPANESE_FUNCTION_WORDS = set(
    'と に は が も を で や へ か には とは '
    'ため こと もの よう まま いく'.split()
)


def strength(text, particle):
    if particle not in text:
        return 0.0
    after = len(text) - text.rfind(particle) - 1
    if after == 0:
        return 1.0
    return 0.35 if particle == '的' and after == 1 else 0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    word = text.strip()
    pronoun = bool(word) and word.startswith(PRONOUNS + DETERMINERS)
    quantifier = bool(word) and word.startswith(QUANTIFIERS)
    grammar = word in FUNCTION_WORDS
    hira = any('\u3040' <= c <= '\u309f' for c in word)
    kata = any('\u30a0' <= c <= '\u30ff' for c in word)
    latin = bool(word) and word.isascii() and word.isalpha()
    stop = bool(word) and word[0] in '。.!！?？:：'

    chinese = 0.8 if len(word) == 1 else 0.6 if len(word) == 2 else 0.4
    if pronoun:
        chinese = 2.3
    elif grammar:
        chinese = 1.9
    elif quantifier:
        chinese = 1.3
    if latin or not word or '�' in word:
        chinese = 0.3
    if word in {',', '，', '、', ';', '；'}:
        chinese = 1.45
    if word and word[0] in '“”「」《》"‘’':
        chinese = 0.9
    if stop:
        chinese = 0.2

    japanese = 0.55 if hira else 0.12 if kata else 0.28
    if grammar or word in JAPANESE_FUNCTION_WORDS:
        japanese = 0.75
    if latin or not word or stop:
        japanese = 0.0
    if 'の' in word:
        japanese *= 0.4

    value = strength(previous, '的') * chinese
    value += strength(previous, 'の') * japanese
    if '的' in word:
        after = len(word) - word.rfind('的') - 1
        value -= (0.0 if word == '的' else 0.07) if after == 0 else (
            0.18 if after == 1 else 0.28
        )
    if 'の' in word:
        value -= 0.07
    if word == 'を':
        value += 0.15
    if previous.endswith(('得', '之', 'な', 'る', 'た')):
        value += 0.17
    elif previous.endswith(('地', 'い', 'く')):
        value += 0.07
    return (doc, text), float(value)

"""An approximate E-initial vocabulary feature, not a general vowel detector.

Word-initial Latin E is strong; Latin E fragments inside words are weak. Capitals,
short identifier fragments and error/exit words strengthen the response.
'Each', eight-related numbers and German indefinite articles are exceptions.
Small lists of vowel-initial associates, Chinese translations of E words,
foreign E-letter spellings and tool-closing markers also respond. Scientific-notation E/e remains positive after a digit;
E inside an all-capitals word is weak. State resets at document boundaries.
"""
import unicodedata

READS = ()
# Whole short words, rather than fragments such as Eq or Ev.
SHORT_WHOLE_WORDS = {'en', 'et', 'el', 'es', 'er', 'em', 'est', 'end'}
INFLECTED_GERMAN_ARTICLES = {'eine', 'einer', 'einen', 'einem', 'eines'}
E_ADVERBS_QUANTIFIERS = {
    'else', 'even', 'every', 'everything', 'everyone', 'everybody',
}
# Alternatives, ownership, order, openness/inclusion, input, time and items.
# These are weak associates, not a rule for every vowel-initial word.
VOWEL_WORD_ASSOCIATES = {
    'or', 'our', 'own', 'owned', 'owner', 'owners',
    'order', 'ordered', 'orders', 'open', 'opened', 'opening',
    'include', 'includes', 'including', 'input', 'inputs',
    'inside', 'outside', 'already', 'item', 'items',
}
# East, elbow, economy, ecology, education, evaluation, example, effect,
# end, event, experience, English, Europe, eye, electricity/electronics,
# elevator, edge, edit, evidence, earth, effort, environment, equal/etc.
E_WORDS_IN_CHINESE = {
    '东', '東', '肘', '经济', '生态', '教育', '评价', '例如', '效果',
    '结束', '事件', '经验', '英文', '英语', '欧洲', '眼', '眼睛',
    '电', '电子', '电梯', '边缘', '编辑', '证据', '地球', '努力', '环境', '等',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\r\n._-(/\\:<>[\'"#*@')
    low = word.lower()
    boundary = token != word or not previous or not previous[-1].isalnum()
    upper = bool(word) and word[0].isupper()
    value = 0.0

    if word and unicodedata.normalize('NFD', low[0])[0] == 'e':
        if low == 'each':
            value = -0.07 if upper else -0.19
        elif low == 'ein':
            value = 0.60
        elif low in INFLECTED_GERMAN_ARTICLES:
            value = 0.0
        elif low.startswith('eight'):
            value = 0.15
        elif low == 'e' and len(word) == 1 and previous[-1:].isdigit():
            value = 1.2
        elif boundary or (upper and not word.isupper()):
            value = 0.98 + 0.20 * upper
            value += 0.23 * (not token[0].isspace())
            short = 1 < len(word) <= 3
            value += 0.25 * (short and low not in SHORT_WHOLE_WORDS)
            value += 0.20 * (short and upper)
            value += 0.25 * low.startswith('err')
            value += 0.80 * low.startswith('exit')
            value -= 0.20 * (low in E_ADVERBS_QUANTIFIERS)
            value -= 0.35 * (low[0] != 'e')
        elif len(word) == 1 and previous[-1:].isupper():
            value = 0.15 if upper else 0.0
        else:
            value = 0.10 + 0.07 * (len(word) == 1 and low[0] == 'e')
            value += 0.20 * upper + 0.40 * (upper and len(word) == 1)
    elif (boundary or upper) and low in VOWEL_WORD_ASSOCIATES:
        value = 0.68
    elif (boundary or upper) and low in {'output', 'outputs'}:
        value = 0.50
    elif low in E_WORDS_IN_CHINESE:
        value = 1.0
    elif low in {'或', '或者', '输入', '输出', '打开', '包括', '进入', '入口', '出'}:
        value = 0.60
    elif boundary and low == 'или':
        value = 0.44
    elif low.startswith('э'):
        value = 0.4 if low.startswith('эт') and len(low) > 2 else 1.8
    elif low in {'え', 'エ', '에'}:
        value = 0.95
    elif token == '</tool_call>':
        value = 1.0
    elif token == '</tool_response>':
        value = 0.45
    return (doc, token), float(value)

"""Negative detector of exposed zh-like spellings: ж, ž, ż, zh, ʒ, ʐ.

Single letters and short Cyrillic syllables respond most strongly; embedding
these letters in longer pieces weakens the response. Five other consonants
receive smaller fixed responses. An echo continues through adjoining letter
pieces, diluted by their length, and stops at spaces or document boundaries.
Completed Unicode letters are recognized even when their bytes were split.
"""
READS = ()

# Strengths for short syllables containing Cyrillic zhe.
ZHE_SYLLABLES = {
    'ож': 9.0,
    'еж': 7.1,
    'аж': 5.7,
    'уж': 6.6,
    'иж': 5.1,
    'жа': 6.1,
    'же': 5.4,
    'жи': 5.2,
    'жу': 4.8,
    'дж': 3.4,
}
OTHER_CONSONANTS = {'ζ': 1.8, 'ذ': 1.8, 'ț': 1.8, 'ţ': 2.6, 'จ': 1.8}


def zhe_strength(word, spaced, uppercase):
    size = len(word)
    if size == 1:
        return 9.2 if spaced or uppercase else 7.8
    if size == 2:
        if spaced and word == 'же':
            return 6.8
        if spaced and word == 'дж':
            return 1.5
        return ZHE_SYLLABLES.get(word, 4.0)
    strength = 4.5 * (3.0 / size) ** 1.7
    if size == 3:
        if spaced and word.endswith('ж'):
            strength *= 0.7
        elif 0 < word.index('ж') < size - 1:
            strength = 3.0 if spaced else 2.0
        elif word in {'руж', 'рож'}:
            strength = 6.8
    elif not word.endswith('ж'):
        strength *= 0.45
        if word[:2] in ZHE_SYLLABLES and word[1] == 'ж':
            strength = ZHE_SYLLABLES[word[:2]] * 0.4
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    echo = carry[1] if same_document else 0.0
    text = prefix.token_strings[-1]
    if same_document and text.strip() and not text.strip().replace('\ufffd', ''):
        decoded = prefix.text_prefixes[-1]
        if decoded and decoded[-1] != '\ufffd':
            text = decoded[-1]
    word = text.strip().lower()
    size = len(word)
    spaced = text[:1].isspace()
    uppercase = text.strip().isupper()
    strength = 0.0
    if 'ж' in word:
        strength = zhe_strength(word, spaced, uppercase)
    elif 'ž' in word:
        strength = (8.0 if spaced or uppercase else 6.1) if size == 1 else 3.2
    elif 'ż' in word:
        strength = 6.6 if size == 1 else 5.7 if size == 2 else 2.0
        if spaced and word == 'że':
            strength = 2.2
        elif size >= 4:
            strength *= 0.45
    elif 'zh' in word:
        strength = (3.2 if spaced else 4.1) if size == 2 else 2.0
        if size >= 4:
            strength = 0.5
    elif word in {'ʒ', 'ʐ'}:
        strength = 4.0
    elif word in OTHER_CONSONANTS:
        strength = OTHER_CONSONANTS[word]
        if word == 'ζ' and uppercase:
            strength = 3.1
    value = -strength
    if text[:1].isalpha():
        cyrillic = any('\u0400' <= c <= '\u04ff' for c in word)
        if cyrillic:
            dilution = 0.46 if size == 1 else 0.25 if size == 2 else 0.16
        else:
            dilution = 0.18 if size == 1 else 0.13 if size == 2 else 0.07
        value += echo * dilution
    return (doc, value), float(value)

programs.luna:
"""A small estimate for verbs in active prose.

The examples suggest stronger responses to content verbs used as an action or
reasoning step than to grammatical words. This requires a nearby subject or
helper word, but does not attempt to understand the larger sentence.
"""
READS = ()

VERBS = frozenset({
    "add", "anticipate", "assume", "build", "choose", "consider", "copy",
    "decide", "design", "determine", "discuss", "evaluate", "explain",
    "find", "formulate", "give", "imagine", "know", "learn", "look",
    "make", "mean", "mention", "need", "notice", "pick", "place", "plan",
    "provide", "read", "reason", "remember", "run", "select", "set",
    "show", "solve", "take", "thank", "think", "try", "understand",
    "use", "work",
})
IRREGULAR_VERBS = {"found": "find", "shown": "show"}
SUBJECTS_AND_HELPERS = frozenset({
    "also", "are", "be", "can", "could", "did", "do", "he", "i", "is",
    "it", "let", "me", "must", "please", "she", "should", "they", "to",
    "we", "will", "would", "you",
})


def is_verb(word):
    if word in VERBS or IRREGULAR_VERBS.get(word) in VERBS:
        return True
    bases = set()
    if word.endswith("ed"):
        bases.update((word[:-2], word[:-1], word[:-2] + "e"))
    if word.endswith("ing"):
        stem = word[:-3]
        bases.update((stem, stem + "e"))
        if len(stem) > 1 and stem[-1] == stem[-2]:
            bases.add(stem[:-1])
    if word.endswith("s"):
        bases.update((word[:-1], word[:-2], word[:-2] + "e"))
    return any(base in VERBS for base in bases)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous = prefix.token_strings[-2].strip().lower()
    if is_verb(word) and previous in SUBJECTS_AND_HELPERS:
        return None, 0.44
    return None, 0.0

programs.haiku:
"""Time-span nouns, signed by the word just before them.

The component fires on a noun naming a span or unit of time (day, hour, year,
time, step, afternoon, ...). After "this" it is positive; after a quantifier or
frequency word ("every", "each", "per", "next", "previous", "one", "an", "all",
"a") it is negative. Magnitude is a fixed 0.3 (a scale chosen on eval; the
observed values range about 0.3 to 1.5). Other time nouns and all other tokens predict 0.
"""

READS = ()

TIME_NOUNS = {
    "day", "days", "hour", "hours", "year", "years", "time", "times",
    "minute", "minutes", "week", "weeks", "month", "months", "step",
    "afternoon", "morning", "evening", "night",
}
THIS_WORDS = {"this", "This"}
QUANTIFIER_WORDS = {
    "every", "each", "per", "next", "previous", "one", "an", "all", "a",
    "shorter", "consecutive",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word not in TIME_NOUNS or len(prefix) < 2:
        return carry, 0.0
    before = prefix.token_strings[-2].strip()
    if before in THIS_WORDS:
        return carry, 0.3
    if before in QUANTIFIER_WORDS:
        return carry, -0.3
    return carry, 0.0

programs.luna:
"""Use a few ordinary phrase cues for the component's time-word responses.
Hours tend to be negative; this/next/every often determine the sign on day,
year, and time. Unrecognized tokens receive zero."""
READS = ()


def clean(text):
    return text.strip().casefold().strip(".,:;!?()[]{}\"'`“”‘’")


def step(carry, prefix, upstream):
    words = prefix.token_strings
    word = clean(words[-1])
    previous = clean(words[-2]) if len(words) > 1 else ""

    if word in {"hour", "hours"}:
        value = -0.30 if word == "hour" else -0.16
    elif word == "day":
        value = {"this": 0.40, "next": -0.45,
                 "every": -0.30, "all": -0.30}.get(previous, 0.0)
    elif word == "year":
        value = {"this": 0.40, "next": -0.40,
                 "previous": -0.40}.get(previous, 0.0)
    elif word == "time":
        value = {"this": 0.35, "great": 0.40,
                 "every": -0.35, "shorter": -0.35}.get(previous, 0.0)
    elif word == "step":
        value = {"this": 0.25, "each": -0.25}.get(previous, 0.0)
    elif word in {"minute", "minutes"}:
        value = -0.16
    elif word == "years":
        value = 0.12
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A local syntax-boundary response, mostly silent on ordinary text.

Math argument starts are positive, especially numbers in fractions and
symbols in font commands. Separately tokenized closing-tag names and HTML
character references are negative. Values are rounded estimates from training examples of
these readable classes, not a vocabulary lookup. A short text tail and the
previous token are retained; both reset at each new document.
"""
import re

READS = ()
GREEK = set((
    'alpha beta gamma delta epsilon varepsilon zeta eta theta vartheta '
    'iota kappa lambda mu nu xi pi varpi rho varrho sigma varsigma tau '
    'upsilon phi varphi chi psi omega Gamma Delta Theta Lambda Xi Pi '
    'Sigma Upsilon Phi Psi Omega'
).split())
FONTS = (
    'mathrm|mathbf|mathbb|mathcal|mathit|mathsf|mathtt|mathfrak|'
    'text|textrm|textbf|textit|texttt|textsf|textnormal|operatorname|'
    'mbox|rm|bf|it|cal|bb|sf|tt'
)
STYLE = re.compile(r'\\(' + FONTS + r')\s*(\{\s*)?(\\)?$')
ARGUMENT = re.compile(r'\\([A-Za-z]+)\s*\{\s*$')
COMMAND = re.compile(r'\\([A-Za-z]+)$')
ACCENTS = set((
    'hat widehat bar overline underline vec tilde widetilde dot ddot '
    'breve check acute grave overrightarrow underbrace overbrace '
    'bm boldsymbol'
).split())
REFERENCES = set('ref label cite eqref pageref url href color'.split())
FRACTIONS = set('frac dfrac tfrac cfrac binom dbinom tbinom'.split())


def response(tail, previous, token):
    word = token.strip()
    if not word:
        return -0.12 if previous.endswith('{\n') else 0.0
    number = word.isdigit()
    symbol = number or (word.isalpha() and
                        (len(word) == 1 or word.isupper()))
    content = word[0].isalnum() or word[0] in '+-*'

    # Markup names and escaped character codes have negative responses.
    if tail.endswith('</') and word[0].isalpha():
        value = -1.55 if len(word) == 1 else -1.08
        return value - (0.4 if previous.endswith('></') else 0.0)
    if tail.endswith('<') and word[0].isalpha():
        return -0.65 if previous.endswith('><') else -0.06
    if tail.endswith('&#') and (number or word == 'x'):
        return -1.07
    if number and re.search(r'&#[xX]?[0-9a-fA-F]+$', tail):
        return -0.54

    if previous.strip() == 'text' and word in {
        'bf', 'it', 'tt', 'rm', 'sf', 'normal', 'up', 'sc', 'width'
    }:
        return -0.45 if word == 'width' else -1.5
    if previous.strip() == 'math' and word in {
        'bb', 'cal', 'rm', 'bf', 'it', 'sf', 'tt', 'frak'
    }:
        return 0.28
    if previous.strip() in {'left', 'right', 'big', 'Big', 'bigg', 'Bigg'}:
        if word[0] in '([{)|]}.\\':
            return {'left': 0.97, 'right': 0.29}.get(previous.strip(), 0.34)

    # Font commands strongly mark the beginning of their argument.
    style = STYLE.search(tail)
    if style:
        font, brace, slash = style.groups()
        if word.startswith('{'):
            if any(c.isalnum() for c in word[1:]):
                return 2.7
            return 1.1 if font == 'text' else 0.6
        old_style = font in {'rm', 'bf', 'it', 'cal', 'bb', 'sf', 'tt'}
        if content and (brace or old_style):
            if slash and word in GREEK:
                return 2.8
            if not brace:
                return 1.6 if symbol else 0.8
            if font in {'textit', 'mathit', 'textnormal'}:
                return 0.68
            return 2.25 if symbol else 1.5

    if previous.endswith('\\') and word in GREEK:
        return 1.34 if previous.endswith('{\\') else 0.46
    if previous.endswith('{\\') and word[0].isalpha():
        return 0.37
    if previous.endswith('\\') and word == 'boxed':
        return -1.18
    command = COMMAND.search(tail)
    if command and command[1] + word in {
        'infty', 'varepsilon', 'varphi', 'vartheta', 'varrho',
        'overline', 'widetilde', 'ldots'
    }:
        return 0.8
    if word.startswith('{') and any(c.isalnum() for c in word[1:]):
        if command:
            return 1.6

    # Other LaTeX arguments, followed by generic braced math.
    argument = ARGUMENT.search(tail)
    if argument and content:
        name = argument[1]
        if name in FRACTIONS:
            return 1.98 if number else 1.2
        if name == 'sqrt':
            return 1.4
        if name in ACCENTS:
            return 1.45
        if name in {'begin', 'end'}:
            return 0.2
        if name in REFERENCES:
            return 1.35 if number else 0.8 if symbol else 0.43
        return 1.45 if number else 1.15 if symbol else 0.45

    if previous.endswith('{') and content:
        if previous.endswith('_{'):
