import re

READS = ()
PYTHON = re.compile(r'\b(?:import |def |self\.|print\(|from \w+[^\n]* import )')
DIRECTIVE = re.compile(r'#\s*(?:include|import|define|ifdef|ifndef|endif|undef)\b')
CODE = re.compile(r'[=;]|\w\(')


def comment_signal(kind, token, previous, text):
    if not previous:
        return -0.16 if kind == '#' else 0.77
    if '\n' in token:
        return 0.6 if kind == '#' else 0.25
    normal = text.replace('\\n', '\n').replace('\\t', '\t')
    lines = [line for line in normal.splitlines() if line.strip()]
    source = [bool(CODE.search(line)) for line in lines[-5:]]
    last_code = bool(source and source[-1])
    recent_code = sum(source) >= 2
    indent = bool(previous) and set(previous) <= set(' \t')
    newline = previous.endswith(('\n', '\\n'))
    escaped = previous.endswith(('\\n', '\\t')) or (
        '\\n' in text[-100:] and '\n' not in text[-100:])
    numbered = bool(re.search(r'\d+\t *$', normal))
    closer = any(c in previous for c in ')]};')
    spaced = token.startswith(' ')
    if kind == '#':
        if PYTHON.search(normal):
            if escaped:
                return 3.2 if indent else 2.0
            imports = sum(bool(re.match(r'\s*(import |from .* import )', line))
                          for line in lines[-5:])
            value = 4.45 if imports >= 2 else 3.4 + 0.6 * last_code + 0.2 * indent
            return value - 0.4 * numbered
        if DIRECTIVE.search(normal):
            return 0.6 if newline or indent else 0.0
        if indent:
            return (2.8 if spaced else 2.1) + 0.8 * last_code - 0.5 * escaped
        if newline:
            return 1.35 + (1.2 if closer else 0.8 * recent_code)
        if previous.endswith(('](', '.md', '.html')):
            return -0.55
        return (1.2 if spaced else 0.45) if recent_code else 0.1
    if escaped:
        return 1.8 if spaced else 1.1
    if recent_code:
        return (2.6 - 0.5 * numbered) if indent else 2.5 if closer else 1.7
    if indent:
        return (1.9 if spaced else 1.55) if numbered else 2.1 + 0.5 * last_code
    return 2.5 if ';' in previous else 2.0 if closer else 1.45 if newline else 0.95


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, text = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    marker = token.strip()
    spaced = token.startswith(' ')
    line_start = previous.endswith(('\n', '\\n')) or previous.isspace()
    value = 0.0
    if marker == '#':
        value = comment_signal('#', token, previous, text)
    elif marker.startswith('//') or ('//' in marker and marker[0] in ';(){}"'):
        if marker.startswith('///'):
            value = 1.05 if spaced else 0.8
        elif marker.startswith('//-'):
            value = 2.0
        elif marker.startswith('"'):
            value = 0.8
        else:
            value = comment_signal('//', token, previous, text)
        if '\n' in token:
            value = 0.23
    elif marker.startswith('/*'):
        value = 1.0 if spaced or line_start else -0.2
        if marker.startswith('/**'):
            value = 0.4 if '\n' in token else 0.65
        elif '\n' in token:
            value = 0.7 if previous else -0.32
    elif marker and set(marker) == {'#'}:
        value = 0.6 if line_start else 0.1
        if len(marker) > 6:
            value = 1.5
    elif marker.startswith('#=') or marker == '#%%':
        value = 3.4
    # A commented-out Python statement can share one token with its hash.
    elif marker.startswith('#') and marker[1:] in {
        'print', 'def', 'return', 'class', 'assert', 'pass'
