    elif marker in {'#include', '#define', '#import'}:
        value = -0.1
    elif marker in {'#if', '#else', '#elif', '#endif', '#ifdef', '#ifndef'}:
        value = 1.6 if marker == '#if' else 0.5
    elif marker == '#[':
        value = 0.55
    elif marker in {'|', '(|', '{|', ')|'}:
        value = 0.49 if '\n' not in token else 0.22
    elif marker == '--':
        value = 1.3 if line_start else 0.3 if spaced else 0.1
        if '\n' in token:
            value = 0.15
    elif marker == '---':
        value = (0.48 if spaced else 0.33) if '\n' not in token else 0.18
    elif marker in {'"""', "'''"}:
        value = 0.65 if '\n' not in token else 0.33
    elif marker in {'(#', '[#'}:
        value = -0.65
    elif marker == '<!--':
        value = 1.0
    elif marker == '%':
        value = 0.6 if line_start else 0.17 if spaced else 0.07
    return (doc, token, (text + token)[-600:]), float(value)

programs.luna:
"""Approximate the response to visible code and document structure markers.

The component is usually quiet, but often responds to comment openers and to
markdown-like headings, table bars, and separator dashes. This predicts a
small marker-specific pulse and otherwise returns zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.strip()
    if not mark:
        return carry, 0.0

    # Comment and heading introducers; the hash is also used for headings.
    if mark.startswith('//'):
        return carry, 1.5
    if mark.startswith('/*'):
        return carry, 0.55
    if mark.startswith('#'):
        if mark.startswith('###'):
            return carry, 0.65
        if mark.startswith('##'):
            return carry, 0.7
        return carry, 1.5

    # Table/alternative bars and separator or option dashes.
    if mark.startswith('|'):
        return carry, 0.52
    if mark.startswith('--'):
        return carry, 0.75
    return carry, 0.0

