LOOKING = {'look', 'looking'}
SEARCH_REQUEST = {'search', 'searching', 'ask', 'asks', 'asking'}
SOLVING = {'solve', 'solved', 'solving', 'compute', 'theorem', 'recurrence'}
FORMULAS = set('''equation equations formula formulas expression expressions
