REASONING = set('check checking see think suppose recall observe prove'.split())
APPLICABILITY = {'that', 'hold', 'holds', 'true', 'possible', 'works'}
TRANSITIONS = set('so then therefore similarly hence thus'.split())
METHODS = set('''method methods test tests code algorithm algorithms solution
solutions rule rules model models evidence function functions useful'''.split())
PROVISION = set('''provide provides provided providing offer offers offered
offering recommendations'''.split())
SUITABILITY = {'suitable', 'room', 'space', 'opportunities'}
QUANTITY = {'number', 'numbers', 'count', 'probability'}


