        (SOLVING, 0.98), (FORMULAS, 0.76), (REASONING, 0.76),
        (APPLICABILITY, 0.79), (TRANSITIONS, 0.53), (METHODS, 0.36),
        (PROVISION, -0.16), (SUITABILITY, -0.20), (QUANTITY, 0.43),
