        elif word in {'the', 'a', 'an', 'this', 'that', 'these', 'those'}:
            value = 0.04 if previous in REASONING | FORMULAS | QUANTITY else 0.0
        elif word in {'answer', 'answers', 'example', 'examples', 'topic', 'topics'}:
            value = 0.15
        elif word in {'study', 'studies', 'write', 'writing'}:
            value = 0.10
        elif word in {
            'again', 'following', 'next', 'future', 'forward',
            'best', 'find', 'think',
        }:
