        elif word in {'support', 'supports', 'supported', 'supporting'}:
            value = -0.12
        elif word in {'they', 'one'}:
            value = 0.05
        elif word in {'are', 'if'}:
            value = 0.025
        elif word in {'have', 'has', 'had'}:
            value = -0.015
    elif token in {'</tool_call>', '</tool_response>'}:
        value = 0.12 if token == '</tool_call>' else 0.087
    elif token == '</think>':
