    " look", " looking", " looked", " looks", " search", " searching", " searches",
    " solve", " solving", " solved", " see", " find", " finding", " ask", " asks",
    " asking", " known", " wait", " waiting", " check", " compute", " test",
    " equation", " equations", " formula", " method", " algorithm", " solution",
    " solutions", " approximation", " expression", " that", " hold", " So", " so",
    " Then", " Wait", " Similarly", " possible", " work", " works",
}
