programs.sol:
"""Estimate the component from short written long-a fragments.

Arabic alif (ا) at the beginning of an unspaced fragment is the main cue.
Its response is diluted in longer tokens and at word boundaries. Some of
it carries onto the next fragment. The -aat and hamza/feminine endings
are weaker. Additional rules cover long-a signs in Thai, Indic scripts and
Latin, while the Arabic short-a mark gets a negative response. State resets
between documents. Unrelated vocabulary-specific variation is left at zero.
"""
READS = ()
ALIFS = 'اآأإ'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    n = len(text)
    spaced = bool(token) and token[0].isspace()
    letters = [c for c in text if c.isalpha()]
    value = 0.0
    if letters and all('\u0600' <= c <= '\u06ff' for c in letters):
        value = -0.04 if spaced else 0.02
        if 'ا' in text:
            if spaced:
                if n <= 2:
                    value += 0.88 if n == 1 else 0.68
                elif n == 3 and not text.startswith('ا'):
                    value += 0.28
            else:
                if n == 1:
                    value += 1.35
                elif n == 2 and text.startswith('ا'):
                    value += 1.9 if text[-1] in 'تءة' else 2.8
                elif text.endswith('ا'):
                    value += 0.9 / n
                else:
                    value += (3.8 if text[-2] == 'ا' else 1.9) / n
                if n >= 3 and text.startswith('ا'):
                    value += 2.1 / n
                if n >= 5:
                    value -= 0.37
        elif not spaced:
            if text.endswith('ة'):
                value += 0.6 / n
            if text.endswith('ى'):
                value += 0.3 / n
        if n == 1 and text in 'آإ':
            value += 0.6
        if previous.endswith(tuple(ALIFS)):
            value += (0.4 if spaced else 1.7) / n
            if not spaced and len(previous.strip()) == 2:
                value += 0.6 / n
        elif any(c in ALIFS for c in previous[-2:]):
            value += (0.03 if spaced else 0.6) / n
    elif text:
        if text == 'َ':  # Arabic SHORT a, in contrast to alif
            value = -0.35
        elif 'า' in text:  # Thai long a
            value = (0.45 if text.endswith('า') else 0.8) * 2 / (n + 1)
        elif 'ा' in text:  # Devanagari long-a sign
            value = 0.85
        elif 'ā' in text.lower():
            value = 0.33 / n
        if not spaced and previous.endswith(('ā', 'Ā', 'า')):
            value += (0.18 if previous.endswith('า') else 0.8) / n
        # Only this rare case needs joined decoding: the preceding Gurmukhi
        # vowel sign may itself have been split into byte-level tokens.
        if '\u0a15' <= text[0] <= '\u0a39' and previous:
            if prefix.text_prefixes[-2].endswith('ਾ'):
                value = 4.3 / n
    return (doc, token), float(value)

