"""A weak script-based proxy: Arabic letters, and occasionally Gurmukhi, get a small lift."""
import unicodedata

READS = ()
BASELINE = 0.001


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if any('ARABIC' in unicodedata.name(ch, '') and ch.isalpha()
           for ch in token):
        return None, 0.37
    if any('GURMUKHI' in unicodedata.name(ch, '') and ch.isalpha()
           for ch in token):
        return None, 0.60
    return None, BASELINE

programs.sol:
"""Approximate negative bursts at boundaries of East Asian text.

A space-led Han/kana token gives a strong negative value, with a weaker value
for function characters and longer tokens. Seven tokenizer fragments mark
unfinished UTF-8 Han/kana prefixes; other undecodable space-led glyphs are
inferred from East Asian writing in the previous eight tokens. Continuation
fragments get a smaller negative tail until decoding completes. There are
also rules for Thai letters, Asian punctuation and quotation/linking markers.
A lone space is weakly negative at document start or after a Han/kana token.
Everything else is zero. State resets at each document boundary. Individual
token strengths and ordinary-text variation are deliberately omitted.
"""

READS = ()
# Space + E5/E6/E7/E8/E9: first byte of a Han ideograph.
SPACE_HAN_FIRST_BYTE = frozenset({4891, 6567, 8908, 10236, 18137})
# Space + E3 82/E3 83: unfinished Japanese syllabary character.
SPACE_KANA_TWO_BYTES = frozenset({17587, 20711})
CHINESE_FUNCTION_WORDS = frozenset('的在是和与为了或若')


def east_asian(c):
    return ('\u3400' <= c <= '\u9fff'
            or '\u3041' <= c <= '\u3096'
            or '\u30a1' <= c <= '\u30fa')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0)
    _, recent_asian, previous, unfinished = carry
    s = prefix.token_strings[-1]
    word = s.lstrip()
    value = 0.0
    remaining = 0

    if int(prefix.token_ids[-1]) in SPACE_HAN_FIRST_BYTE:
        value, remaining = -1.21, 2
    elif int(prefix.token_ids[-1]) in SPACE_KANA_TWO_BYTES:
        value, remaining = -1.55, 1
    elif s.startswith(' ') and word:
        if east_asian(word[0]):
            if word in CHINESE_FUNCTION_WORDS:
                value = -1.58
            else:
                value = -2.65 if len(word) == 1 else -2.0
        elif word == '\ufffd' and recent_asian:
            value, remaining = -1.77, 1
        elif '\u0e01' <= word[0] <= '\u0e45' and word[0].isalpha():
            value = -2.0
        elif word[0] in '・、。':
            value = -0.65
        elif word[0] in '【（':
            value = -1.05
    elif s.startswith('，') and len(s) > 1 and east_asian(s[1]):
        value = -1.07 if s == '，则' else -1.55
    elif s == '」と':
        value = -1.04
    elif s == '”的':
        value = -0.60
    elif unfinished and s.startswith('\ufffd'):
        value = -0.80 if unfinished == 2 else -0.51
        if prefix.text_prefixes[-1].endswith('\ufffd'):
            remaining = 1
    elif s == ' ':
        if not previous:
            value = -0.128
        elif any(east_asian(c) for c in previous):
            value = -0.51

    recent_asian = ((recent_asian << 1) | any(east_asian(c) for c in s)) & 255
    return (doc, recent_asian, s, remaining), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2264: a "stray space in Chinese/Japanese text" detector.

What it responds to: a space placed directly in front of a Chinese or Japanese character,
inside text that is itself Chinese or Japanese. Such spaces are unusual there, and the
component writes a negative signal on them. The signal grows with how CJK the recent text is.

Cases, all judged from the current token (its string as the tokenizer splits it):
  * a space followed by a CJK character in the same token (" 提", " 新"): about -2 to -4;
  * a space followed by the first byte of a multi-byte character (decodes alone as " �"),
    which in CJK text is almost always a CJK character starting: about -1.5 in CJK text;
  * a bare space token in CJK text: a weaker negative;
  * a full-width comma glued to a Chinese word ("，在", "，并"): about -1.5.

CJK share = fraction of non-space characters among the last WINDOW tokens of the same
document that are CJK (Han, kana, CJK punctuation). Everything else is predicted as 0.
"""

READS = ()

WINDOW = 16  # earlier tokens of the same document that count as context


def is_cjk(c):
    """Han ideographs, Japanese kana and CJK punctuation: U+3000 to U+9FFF."""
    return "　" <= c <= "鿿"


def cjk_share(strings):
    """Fraction of non-space characters that are CJK, over the given token strings."""
    chars = [c for s in strings for c in s if not c.isspace()]
    if not chars:
        return 0.0
    return sum(is_cjk(c) for c in chars) / len(chars)


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    doc = prefix.document_ids[t]
    lo = max(0, t - WINDOW)
    earlier = [
        prefix.token_strings[i] for i in range(lo, t) if prefix.document_ids[i] == doc
    ]
    share = cjk_share(earlier)  # 0 (no CJK) to 1 (all CJK)
    if token == " ":
        return carry, -0.7 * share
    if token[:1] == " " and len(token) > 1:
        rest = token[1:]
        if is_cjk(rest[0]):
            return carry, -(1.9 + 1.6 * share)
        if "�" in rest:  # space + first byte of a multi-byte character
            return carry, -(0.25 + 1.8 * share)
    if token[:1] == "，" and any(is_cjk(c) for c in token[1:]):  # full-width comma
        return carry, -1.5
    return carry, 0.0

programs.luna:
"""Use isolated U+FFFD spellings as a small cue for negative activations.

The strongest pattern is a space-prefixed replacement mark; prior punctuation,
spacing, or another mark adjusts that estimate. Other marks get smaller values.
"""
import unicodedata

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ""
    if len(prefix.token_strings) > 1:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        if same_doc:
            previous = prefix.token_strings[-2]

    if token == " �":
        if "�" in previous:
            return None, -0.20
        prior_text = previous.rstrip()
        if prior_text and unicodedata.category(prior_text[-1]).startswith("P"):
            return None, -1.00
        if previous.startswith(" "):
            return None, -0.43
        return None, -0.84
    if token.count("�") > 1:
        return None, -0.42
    if "�" in token:
        return None, -0.07
    return None, 0.0

programs.sol:
"""Detect completions of adding, writing, rounding and reducing phrases.

Negative responses are strongest for 'add up/to', 'sum up', 'write down',
and 'round down'. Weaker responses mark assembling or reducing expressions
such as 'build up' and 'break down'. Short object phrases may intervene.
A few Chinese adding/summarizing constructions are treated similarly.
There are small baseline biases for particles and aggregate words; most
unrelated vocabulary effects are deliberately left at zero.
"""
import re

READS = ()
DIRECT = {
    'add': {'to': -0.97, 'up': -1.76, 'all': -0.64, 'more': -0.80,
            'together': -1.15, 'on': -0.92, 'ons': -0.90,
            'them': -0.47, 'it': -0.25, 'new': -0.50, 'back': -0.79},
    'sum': {'up': -1.45, 'to': -0.38, 'over': -0.64, 'all': -0.55,
            'them': -0.77, 'together': -0.90},
    'write': {'down': -1.67, 'out': -0.80, 'up': -0.89, 'to': -0.21},
    'round': {'down': -1.35, 'up': -1.09, 'off': -0.74, 'to': -0.24},
    'multiply': {'out': -0.93, 'all': -0.49, 'both': -0.24},
    'addition': {'to': -0.59},
}
# Verb classes group the weaker completions by their everyday meaning.
GROUPS = {
    'up': [(set('build clean wrap fill mix tidy pile warm'.split()), -0.64),
           (set('make set put'.split()), -0.19)],
    'down': [(set('break calm cool lay close slow fold'.split()), -0.60),
             (set('note jot narrow boil'.split()), -0.88)],
    'out': [(set('cancel factor filter fill comment'.split()), -0.65),
            (set('lay print'.split()), -0.40)],
    'to': [(set('contribute contribution'.split()), -0.22)],
    'all': [(set('combine summarize'.split()), -0.50),
            (set('remove list collect'.split()), -0.25)],
    'together': [(set('put combine mix'.split()), -0.30)],
}
ROOTS = set(DIRECT) | set().union(
    *(verbs for groups in GROUPS.values() for verbs, _ in groups)
)
IRREGULAR = {'wrote': 'write', 'written': 'write', 'built': 'build',
             'broke': 'break', 'broken': 'break', 'laid': 'lay', 'made': 'make'}
BASE = {'down': -0.10, 'up': 0.02, 'out': -0.01, 'together': -0.10,
        'everything': -0.17, 'terms': -0.08, 'more': -0.03}
OBJECTS = set(
    'it them me you this that all everything these those something '
    'someone him her us both'.split()
)


def family(word):
    if word in IRREGULAR:
        return IRREGULAR[word]
    candidates = [word]
    if word.endswith('s'):
        candidates.append(word[:-1])
    for ending in ('ing', 'ed'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            candidates += [stem, stem + 'e']
            if len(stem) >= 2 and stem[-1] == stem[-2]:
                candidates.append(stem[:-1])
    return next((w for w in candidates if w in ROOTS), word)


def phrase(root, word):
    if word in DIRECT.get(root, {}):
        return DIRECT[root][word]
    for verbs, value in GROUPS.get(word, []):
        if root in verbs:
            return value
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-_')
    match = re.search(r'([A-Z]?[a-z]+|[A-Z]+)$', recent)
    previous = match.group(1).lower() if match else ''
    root = family(previous)
    value = BASE.get(word, 0.0) if token[:1].isspace() else 0.0
    amount = phrase(root, word)
    if amount is not None:
        value = amount
        if previous in {'added', 'built', 'laid', 'cooled', 'wrapped',
                        'filtered', 'printed', 'written', 'wrote'}:
            value *= 0.72
        if root == 'add' and word == 'to':
            value = -0.85 if previous == 'added' else -0.97
        if previous == 'filtered' and word == 'out':
            value = -0.25
    elif root == 'add':
        value = -0.03 if previous == 'added' else -0.08
    if word in {'to', 'up', 'down', 'out', 'together'}:
        words = re.findall(r'[a-z]+|[0-9]+|[^\w\s]', recent.lower())
        for distance, w in enumerate(reversed(words[-7:])):
            if w in '.!?;:':
                break
            verb = family(w)
            if verb not in ROOTS:
                continue
            if distance == 0:
                if word == 'to' and verb != 'add':
                    continue
                break
            if word == 'to' and verb == 'add':
                strength = 0.35 if w == 'added' else 0.57
                value = min(value, -strength * 0.77 ** (distance - 1))
            elif distance <= 3 and (previous in OBJECTS or word == 'together'):
                amount = phrase(verb, word)
                if amount is not None:
                    value = amount * 0.90 ** distance
            break
    # Completing the mathematical noun 'summation(s)'.
    if previous == 'summ' and word in {'ation', 'ations'}:
        value = -0.62 if word == 'ation' else -0.85
    # The stems of 'summing' and 'summary'.
    if previous == 'sum' and word in {'ming', 'mar'}:
        value = -0.30
    if token in {'起来', '出来', '一下', '下来', '到'}:
        if recent.endswith(('总结', '整理', '添加', '加')):
            value = -0.45 if token == '到' else -0.85
        elif token == '下来' and recent.endswith('写'):
            value = -0.75
    return (doc, (recent + token)[-160:]), float(value)

programs.luna:
"""A sparse lexical sketch: relational particles lean negative, and recent
adding words sharpen that cue; "all" and "together" also turn negative after
adding language. "All" has a second cue after "let me [verb]". The literal
words "local" and ".log" get small positive guesses; other tokens are zero.
"""
import re

READS = ()

PARTICLES = frozenset({
    "to", "up", "down", "out", "into", "off", "on", "over", "back",
    "around", "through", "across", "away", "along", "apart",
})
ADD_WORD = re.compile(r"\b(?:add|adds|added|adding|addition)\b", re.I)
LET_ME_VERB = re.compile(r"\blet\s+me\s+\w+\s*$", re.I)

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = "" if carry is None or carry[0] != doc else carry[1]

    raw = prefix.token_strings[-1]
    word = raw.strip(" \t\r\n,;:!?()[]{}\"'").casefold()

    if word == ".log":
        value = 0.10
    elif word == "local":
        value = 0.08
    elif word in PARTICLES or word == "all":
        recent = history[-64:]
        if ADD_WORD.search(recent):
            value = -0.40
        elif word == "all" and LET_ME_VERB.search(recent):
            value = -0.45
        elif word == "down":
            value = -0.16
        elif word == "up":
            value = -0.055
        elif word == "out":
            value = -0.03
        elif word == "to":
            value = -0.01
        else:
            value = -0.02
    elif word == "together" and ADD_WORD.search(history[-64:]):
        value = -0.40
    else:
        value = 0.0

    return (doc, (history + raw)[-100:]), float(value)

programs.sol:
"""A negative response to composition, inclusion, and means of construction.

The word lexicon covers a whole and its parts ('comprises', 'consists',
'involves', 'includes'), requirements, and extent. Short phrase rules mark
'consists of', 'made up of', 'formed by', and 'based on' more strongly.
Other tokens are mostly zero. These are approximate lexical strengths:
this is not a general semantic parser, and ignores small residual responses.
"""
READS = ()


def strengths(groups):
    return {word: value for value, words in groups for word in words.split()}


PARTS = strengths([
    (-5.9, 'comprises comprising'),
    (-4.0, 'comprise comprised'),
    (-3.6, 'consist consisted'),
    (-3.3, 'consists involve involves'),
    (-3.0, 'consisting'),
    (-2.5, 'involving'),
    (-1.9, 'involved'),
    (-1.7, 'encompass'),
    (-2.1, 'encompasses entails'),
    (-1.55, 'composed'),
    (-1.25, 'includes'),
    (-1.2, 'mainly'),
    (-1.0, 'entirely'),
    (-0.83, 'include including require requires primarily'),
    (-0.72, 'involvement capable constitute constitutes'),
    (-0.63, 'contain contains characterized'),
    (-0.48, 'contained containing included formed requiring'),
    (-0.33, 'required done'),
    (-0.25, 'made'),
])

# The preceding verb distinguishes production from ordinary 'by' phrases.
BY = strengths([
    (-4.9, 'formed'), (-4.6, 'composed'),
    (-3.0, 'constructed characterized'),
    (-2.4, 'made built'), (-2.2, 'developed contributed'),
    (-2.1, 'represented performed'),
    (-1.9, 'created produced defined done established conducted'),
    (-1.7, 'accompanied determined achieved'),
    (-1.55, 'calculated generated obtained'),
    (-1.35, 'written owned measured'),
    (-1.2, 'caused driven'), (-1.1, 'designed controlled'),
    (-1.0, 'followed described shown'),
    (-0.5, 'directed inspired affected influenced'),
    (-0.2, 'divided divisible multiplied dividing'),
    (-0.08, 'required'),
])

# A few translations of inclusion/composition and means.
OTHER = {'包括': -2.75, '主要包括': -3.6, '其中包括': -2.1,
         '包含': -1.1, '由': -1.4, '是由': -1.6,
         '涉及': -1.6, '涉及到': -1.7, '通过': -0.52,
         'состоит': -1.5, 'besteht': -1.4, 'gồm': -2.3}

