DEPENDENCE = {'depend', 'depends', 'dependent', 'rely', 'relies', 'reliant'}
MODALS = {'may', 'can', 'could', 'will', 'shall', 'should', 'might'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
