        elif previous == 'up' and before == 'made':
            value = -4.0
        elif previous == 'out' and before == 'made':
            value = -2.0
        elif previous in {'made', 'formed'}:
            value = -2.4
        elif previous in {'capable', 'full', 'involvement'}:
            value = -1.0
        elif previous in {'composition', 'mix', 'mixture'}:
