    elif token in {' on', ' upon'}:
        if previous == 'based':
            value = -1.4
        elif previous in {'built', 'build', 'builds', 'building'}:
            value = -0.8
        elif previous in DEPENDENCE:
            value = -0.55
        elif previous in {'depending', 'depended', 'dependence'}:
            value = -0.3
        if token == ' upon':
            value *= 0.75
    elif token == ' from':
        if previous in {'made', 'formed'}:
            value = -2.4
        elif previous in {'built', 'constructed'}:
            value = -1.5
        elif previous in {'resulted', 'resulting'}:
            value = -0.95
        elif previous in {'derived', 'produced', 'arise', 'arises'}:
