programs.haiku:
"""Layer-0 MLP down_proj, component 2266: a negative-going "parts and makers" detector.

The component dips negative on words that say what a thing is made of, or who or what
made or defines it:

- verbs of composition: "comprises" (about -6), "comprising", "consists" / "consisting" /
  "consisted", "involves" / "involving" (about -2 to -4), "composed", "constitutes";
- the "of" right after such a verb: "consists *of*" (about -6), "comprised *of*";
- the "by" that names the maker or means after a made/defined verb: "formed *by*" (about
  -4), "characterized *by*", "developed *by*", "made *by*" (about -2);
- other "by" (about -0.7), and "include"/"contain"/"require" (about -0.7);
- "based *on*" (about -1.3), and a few Chinese equivalents ("包括" include, "由" by).

Everything else is about zero. The program is pure word lookup on the current token and
the one before it, so it needs no carry state.
"""

READS = ()

# Verbs of composition: a thing consists of, comprises, or involves its parts.
COMPOSE = {
    "comprise", "comprises", "comprising", "comprised", "consist", "consists",
    "consisting", "consisted", "compose", "composed", "composes", "composing",
    "constitute", "constitutes", "encompass", "encompasses", "involve", "involves",
    "involving", "involved",
}
# Milder verbs of inclusion or requirement.
INCLUDE = {
    "include", "includes", "including", "included", "contain", "contains",
    "containing", "require", "requires", "required", "requiring",
}
# Verbs of making, forming or defining: the "by" after them names the maker or means.
MADE_BY = {
    "formed", "characterized", "made", "developed", "produced", "obtained",
    "generated", "defined", "determined", "designed", "caused", "achieved",
    "represented", "established", "conducted", "constructed", "built",
}
# Chinese equivalents: include, by, involve, compose.
OTHER_LANG = {"包括": -2.5, "由": -1.4, "涉及": -1.5, "组成": -3.0, "构成": -3.0}
# Forms of "rely on" / "based on" take a mild "on".
BASED_ON = {"based", "rely", "relies", "relying"}


def step(carry, prefix, upstream):
    """Activation at the newest token of the prefix (the word whose next token is predicted)."""
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in OTHER_LANG:
        value = OTHER_LANG[word]
    elif word in COMPOSE:
        value = -4.0
    elif word in INCLUDE:
        value = -0.7
    elif word == "of" and prev in COMPOSE:
        value = -6.0
    elif word == "by" and prev in MADE_BY:
        value = -2.0
    elif word == "by":
        value = -0.7
    elif word == "on" and prev in BASED_ON:
        value = -1.3
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A lexical 'and' response, plus local selection of counted/ordered items.

'And' is excited on its own. Quantities and sequence units are excited after
ordering words (first, next, last), and less strongly after other selectors.
Function words immediately after ordering words instead get a negative value.
These are broad word-class rules, not token-ID statistics.
"""
READS = ()

ORDER = set('first next last second third fourth fifth sixth seventh eighth '
            'ninth tenth previous final following subsequent preceding'.split())
RELATIVE = set('other another top bottom upper lower left right middle outer '
               'inner front back above below past future early late later'.split())
DETERMINERS = set('this that these those which any each every same'.split())
QUANTITIES = set('one two three four five six seven eight nine ten few several '
                 'couple half quarter'.split())
SEQUENCE_UNITS = set('term step line layer row column section paragraph chapter '
                     'digit character number page word letter sentence element'.split())
TIME_UNITS = set('minute hour day week month decade generation round phase stage'.split())
LONG_UNITS = set('year time century season episode game'.split())
PARTS = set('part piece side segment pair set group level'.split())
FUNCTION_WORDS = set('of the a an to in on at for from with as'.split())


def word(token):
    return token.strip().strip('._-').lower()


def predict_token(token, previous):
    w, before = word(token), word(previous)
    if w == 'and':
        if token.strip().isupper():
            return 0.73 if token[:1].isspace() else 0.43
        if token.strip().istitle():
            return 0.89
        if not token[:1].isspace():
            return 0.70
        if ',' in previous:
            return 0.84
        if before.isdigit() or previous.rstrip().endswith((')', ']', '%')):
            return 0.95
        return 1.06

    if before in ORDER:
        qscale = 1.0 if before in ('first', 'next', 'last') else 0.77
        uscale = 1.0
    elif before in RELATIVE:
        qscale, uscale = 0.7, 0.5
    elif before in DETERMINERS:
        qscale, uscale = 0.4, 0.2
    else:
        qscale, uscale = 0.0, 0.0
    if w in QUANTITIES:
        gain = {'one': 2.0, 'two': 3.5, 'three': 3.0,
                'few': 2.7, 'half': 1.8, 'quarter': 1.4}.get(w, 2.0)
        return gain * qscale
    singular = w[:-1] if w.endswith('s') else w
    if singular in SEQUENCE_UNITS:
        return 1.3 * uscale
    if singular in TIME_UNITS:
        return 1.0 * uscale
    if singular in LONG_UNITS:
        return 0.5 * uscale
    if singular in PARTS:
        return 0.8 * uscale
    if token == ' ' or w.isdigit():
        return 0.5 * uscale
    if before in ORDER:
        if w in FUNCTION_WORDS:
            return -0.6 * qscale
        if token.strip() == ',':
            return -0.3 * qscale
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    return None, float(predict_token(prefix.token_strings[-1], previous))

programs.luna:
"""A lexical approximation for a weak, sparse response to names and eponyms.
The carry joins subword fragments into the current word, resetting at document
boundaries. Familiar surname/eponym completions get a stronger negative value;
other capitalized words get a small negative value, and all else gets zero.
"""
READS = ()

EPONYMS = {
    "Ampere", "Cullen", "Einstein", "Franklin", "Hamilton", "Heisenberg",
    "Jefferson", "Lenz", "Schroeder", "Twain", "Woodall",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    for ch in prefix.token_strings[-1]:
        if ch.isspace() or (not ch.isalnum() and ch not in "'-’"):
            word = ""
        else:
            word += ch

    if word in EPONYMS:
        value = -0.35
    elif len(word) >= 4 and (word[0].isupper() or word.isupper()):
        value = -0.016
    else:
        value = 0.0
    return (doc, word), value

"""Approximate the component as a detector for long strings of numerals.

Its negative response grows as a number accumulates digits; commas, decimal
points, and a space within the run get a smaller response. Words reset the run.
"""
READS = ()

_SEPARATORS = set(",./:;%-+()[]")


def _digit_response(previous_digits):
    """A longer numeric prefix gets a progressively stronger response."""
    n = min(previous_digits, 8)
    if n <= 1:
        return -0.02 * n
    if n <= 4:
        return -0.07 - 0.105 * (n - 2)
    if n <= 6:
        return -0.28 - 0.04 * (n - 4)
    return -0.36 - 0.08 * (n - 6)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    old_document, digits, used_space = carry or (document, 0, False)
    if document != old_document:
        digits, used_space = 0, False

    visible = token.strip()
    digit_count = sum(char.isdigit() for char in visible)
    number = digit_count and all(
        char.isdigit() or char in _SEPARATORS or char.isspace()
        for char in visible
    )

    if number:
        # For a token containing several digits, treat all but its last digit
        # as part of the prefix already visible within that token.
        value = _digit_response(digits + max(0, digit_count - 1))
        digits = min(8, digits + digit_count)
        used_space = False
    elif visible and all(char in _SEPARATORS for char in visible):
        value = -0.15 if digits >= 8 and visible in {",", "."} else 0.0
    elif token and token.isspace():
        value = -0.04 if digits >= 6 else 0.0
        if digits and not used_space:
            used_space = True
        else:
            digits, used_space = 0, False
    else:
        value = 0.0
        digits, used_space = 0, False

    return (document, digits, used_space), float(value)

programs.sol:
"""An a-context detector with two main signs.

Negative: English quantity/degree expressions such as 'a little', 'a bit',
'a few' and 'a single', with weaker responses to other amounts/durations.
Positive: a-ending pieces followed by nasal/liquid letter fragments,
especially n, across several alphabets and Japanese/Korean syllables.
The i/e vowel joins are weakly negative; longer positive fragments weaken.
Spacing separates whole-word quantity phrases from spelling fragments.
Strengths approximate recurring training responses; lexical/encoding
exceptions are intentionally left unmodeled.
Keep just two previous tokens and reset them at document boundaries.
"""
import unicodedata
from functools import lru_cache

READS = ()

# Familiar amounts, degrees and durations, grouped by measured strength.
QUANTITY = {'little': -9.0, 'bit': -4.6, 'few': -3.8, 'tad': -3.5}
for words, strength in (
    ('single couple', -2.2),
    ('touch bunch handful thousand', -1.6),
    ('lot tiny million while moment', -1.25),
    ('one dozen', -1.0),
    ('more less hundred minute ton', -0.65),
    ('small much short long', -0.4),
):
    QUANTITY.update(dict.fromkeys(words.split(), strength))


# Nasal/liquid spellings; kana entries are syllables rather than letters.
SONORANT_JOIN = {}
for characters, strength in (
    ('nнνնनণন', 3.4),
    ('mмմमম', 1.5),
    ('μ', 2.15),
    ('rрրռरরنر', 1.8),
    ('م', 0.8),
    ('ρ', 2.9),
    ('λ', 1.35),
    ('łլलল', 0.6),
    ('ン', 3.6),
    ('ナネ', 3.0),
    ('ニヌノラ', 1.5),
    ('リルレロマミムメモなにぬねのんまみむめもらりるれろ', 1.0),
):
    SONORANT_JOIN.update(dict.fromkeys(characters, strength))


@lru_cache(8192)
def a_ending(token):
    word = token.rstrip().lower()
    while word and unicodedata.combining(word[-1]):
        word = word[:-1]
    if not word:
        return 0.0
    last = word[-1]
    hangul = ord(last) - 0xAC00
    if 0 <= hangul < 11172:
        open_a = hangul % 28 == 0 and (hangul // 28) % 21 == 0
        return 0.8 if open_a else 0.0
    ch = unicodedata.normalize('NFKD', last)[0]
    if ch == 'a':
        if len(word.strip()) > 1:
            return 0.6
        return 0.7 if last == 'â' else 1.0
    if ch in 'αаяاآأإաाআ':
        return 1.0
    if ch in 'アカガサザタダナハバパマヤラワャァ':
        return 0.8
    if ch in 'あかがさざただなはばぱまやらわゃぁ':
        return 0.3
    return 0.0


@lru_cache(8192)
def joining_fragment(token):
    word = token.lstrip(' _-.([{/')
    if not word:
        return 0.0
    first = unicodedata.normalize('NFKD', word[0].lower())[0]
    if token[0].isspace():
        # Whole new words are not letter joins, except isolated Latin letters.
        if len(word) != 1:
            return 0.0
        return {'n': 2.2, 'm': 0.8, 'r': 0.9}.get(first, 0.0)
    if first in 'ie':
        return -0.75 if first == 'i' else -0.5
    strength = SONORANT_JOIN.get(first, 0.0)
    hangul = ord(word[0]) - 0xAC00
    if 0 <= hangul < 11172 and hangul // 588 in (2, 5, 6):
        strength = 1.4  # Initial Korean n, r/l or m.
    if first in 'nmr' and len(word) == 1 and not word[0].isupper():
        strength = {'n': 2.0, 'm': 0.7, 'r': 1.4}[first]
    length_scale = len(word) ** -0.5
    if len(word) >= 4:
        length_scale *= 0.4
    return strength * length_scale


@lru_cache(8192)
def article_a(token):
    # The article can share its token with a dash, quote or escaped newline.
    token = token.replace('\\n', '\n').replace('\\t', '\t')
    return token.lstrip(" \t\r\n—–-\"'‘’“”([{").rstrip().lower() == 'a'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    word, prev_word = token.strip().lower(), previous.strip().lower()
    before_word = before.strip().lower()
    vowel = a_ending(previous)
    if previous and all(unicodedata.combining(c) for c in previous):
        vowel = a_ending(before)
    value = vowel * joining_fragment(token)
    if article_a(previous) and word in QUANTITY:
        value = QUANTITY[word]
        if word == 'few' and before_word == 'quite':
            value = -1.7
    elif article_a(before):
        if prev_word in ('little', 'tiny', 'tad', 'small') and word == 'bit':
            value = -3.3
        elif prev_word == 'couple' and word == 'of':
            value = -1.15
        elif previous and all(c in '_{[(^\x00' for c in previous):
            value = joining_fragment(token) / len(previous)
        elif prev_word.isalpha() and word in ('little', 'bit', 'few'):
            value = 0.2 * QUANTITY[word]
    return (doc, token, previous), float(value)

"""Approximate opening pulses, disjunctions, and existential constructions.

Document openings are positive, especially headings, code declarations,
chat starts and common English opening words. Away from the opening, 'or'
and several equivalents are negative; recent 'either/any/not/no' softens
English 'or'. Existential 'there is/was/be' is positive. Other tokens get a
small baseline. State tracks the previous token, a fading qualifier cue,
and how recently the word 'there' occurred.
"""
READS = ()

# Alternative conjunctions and the programming disjunction operator.
ALTERNATIVES = {
    '或': -0.42,
    '或者': -0.31,
    '或是': -0.32,
    'или': -0.24,
    'oder': -0.20,
    'eller': -0.21,
    'ou': -0.11,
    'nor': -0.16,
    '_or': -0.40,
    '||': -0.08,
}


def opening(text):
    word = text.strip()
    if text.startswith('<|'):
        return 0.45 if word == '<|im_start|>' else 0.30
    if word and set(word) == {'#'}:
        return max(0.15, 1.36 - 0.24 * (len(word) - 1))
    if text.startswith(('#include', '/*', '//', '"""')):
        return 0.75
    if text.startswith('#'):
        return 0.50
    # Explicit document headers: module declaration or title label.
    if text in ('package', 'Title'):
        return 1.20
    if text == 'import':
        return 0.93
    if text in ('from', 'export', 'def', 'class', 'const', 'using'):
        return 0.60
    if text in ('The', 'This'):
        return 0.58
    if text in ('I', 'You', 'We'):
        return 0.46
    if text in ('What', 'How', 'Is'):
        return 0.63
    if not word:
        return 0.055 if text == ' ' else 0.23
    if text[0].isspace():
        return 0.41 if word == 'and' else 0.18
    if word.isascii() and word.isalpha():
        return 0.28 if word[0].isupper() else 0.10
    return 0.145


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip()
    first = carry is None or carry[0] != doc
    _, previous, qualifier, there_age = (doc, '', 0.0, 99) if first else carry
    prev_word = previous.strip().lower()
    value = opening(text) if first else -0.003
    if not first:
        if word.lower() == 'or':
            if word == 'OR':
                value = -0.27 if text[0].isspace() else -0.06
            elif word == 'Or':
                value = -0.39 if text[0].isspace() else -0.46
            elif text[0].isspace():
                value = -0.49
            else:
                value = -0.06 if previous[-1:].isalnum() else -0.34
            value += qualifier
        elif word in ALTERNATIVES:
            value = ALTERNATIVES[word]
        elif word in ('is', 'was', "'s", '’s', 'are', 'were', 'exists', 'be'):
            if prev_word == 'there':
                value = 0.35 if word in ('is', "'s", '’s') else 0.29
                if word in ('are', 'were', 'exists'):
                    value = 0.16
            elif word == 'be' and there_age < 4:
                value = 0.31
    qualifier *= 0.82
    if word.lower() in ('either', 'any', 'not', 'no'):
        qualifier = 0.30 if word.lower() in ('either', 'any') else 0.20
    there_age = 0 if word.lower() == 'there' else min(99, there_age + 1)
    return (doc, text, qualifier, there_age), float(value)

"""Sparse structural and lexical response, leaving ordinary tokens at zero.

Negative cues include a non-breaking space, thinking/closing-tool tags,
'easy' and 'less'. Repeated tabs, likelihood words, 'entire', extrema,
'again' and 'today' are positive. Small offsets cover grammatical words
and detached English affixes. Non-breaking-space estimates are damped
to avoid overcorrecting this variable cue. These mixed spelling-sensitive
cues do not establish a unified semantic function. Only the previous
token is retained; a new document resets it.
"""
READS = ()

PUNCTUATION = {'[': 0.024, ']': -0.009, '`': -0.017, '^': -0.014}

# Closed-class English words; only space-prefixed lowercase forms use these.
GRAMMAR = {
    'an': -0.016, 'be': -0.013, 'am': 0.046, 'been': -0.017,
    'do': -0.027, 'done': -0.054, 'shall': -0.037, 'should': 0.041,
    'their': 0.030, 'us': 0.032, 'its': 0.017, 'my': -0.016,
    'other': -0.021, 'another': 0.044, 'those': 0.033, 'every': 0.033,
    'same': -0.028, 'also': -0.027, 'yet': 0.053, 'although': 0.056,
    'where': -0.028, 'who': 0.031, 'whom': 0.051,
    'how': 0.028, 'why': 0.036,
}
# Detached fragments, not matching arbitrary substrings of whole words.
SUFFIXES = {
    's': -0.012, 'ed': -0.031, 'ing': -0.023, 'er': -0.023,
    'ers': -0.042, 'ation': -0.050, 'able': -0.036, 'ure': -0.049,
}
PREFIXES = {'con': -0.060, 'un': -0.020, 're': 0.039, 'pre': 0.038}


def lexical_value(s, previous, first):
    if s == '\xa0':
        if not previous:
            return -0.070
        if '\n' in previous:
            return -0.170
        if previous.count('\xa0') >= 2:
            return -0.040
        if previous[-1].isspace():
            return -0.088
        return -0.115 if previous[-1].isdigit() else -0.148
    if s == '\r':
        return -0.063
    if s and not s.strip('\t'):
        return -0.016 if len(s) == 1 else min(0.09, 0.018 + 0.012 * len(s))
    if s.isspace():
        lines = s.count('\n')
        return (0.005 if lines <= 2 else -0.020) if lines else 0.0
    if s == '<think>':
        return -0.078
    if s == '</think>':
        return -0.166
    if s in {'</tool_call>', '</tool_response>'}:
        return -0.047
    if s == '<|im_start|>':
        return 0.110 if first else 0.009
    if s == 'Title' and first:
        return -0.441
    if s in {'the', 'and', 'of'}:
        if first:
            return 0.25
        if previous and previous[-1].isspace():
            return 0.11
        return 0.04 if previous and previous[-1].isalpha() else 0.08

    word = s.strip()
    if word in PUNCTUATION:
        return PUNCTUATION[word]
    if word in {'NULL', 'null'}:
        return -0.085 if word == 'NULL' else -0.035
    w = word.lower()
    if w in {'again', 'today'}:
        return 0.105
    if w in {'likely', 'unlikely', 'likelihood', 'probability',
             'probabilities', 'probably', 'improbable'}:
        return 0.080
    if w in {'entire', 'entirely'}:
        return 0.097
    if w in {'maximum', 'minimum', 'maximal', 'minimal'}:
        return 0.060
    if w in {'easy', 'easier', 'easiest'}:
        return -0.080
    if w == 'easily':
        return -0.027
    if w == 'less':
        return -0.096 if s.startswith(' ') else -0.064
    if w in {'provide', 'provides', 'provided', 'providing'}:
        return 0.050
    if s.startswith(' ') and word.islower():
        if w in {'he', 'she', 'her', 'him'}:
            return -0.022
        if w in {'some', 'many', 'much'}:
            return -0.030
        if w in {'myself', 'yourself', 'himself', 'herself', 'itself',
                 'ourselves', 'yourselves', 'themselves'}:
            return 0.027
        if w in {'thou', 'thee', 'thy', 'thine'}:
            return 0.080
        return GRAMMAR.get(w, PREFIXES.get(w, 0.0))
    return SUFFIXES.get(s, 0.0)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    value = lexical_value(s, previous, first)
    if s == '\xa0':
        value *= 0.8
    return (document, s), float(value)

"""Estimate responses to individually tokenized E-family characters.

Greek epsilon variants receive large positive values. Latin and Cyrillic E,
E-sound kana, Korean 에, and Hebrew vowel marks have their own estimates.
The spelling 'epsilon' and its 'psilon' suffix are also recognized.
Leading whitespace/punctuation modifies some values. A split UTF-8 character
is recognized at its final byte, without borrowing across document boundaries.
Everything else is zero: no general response to E inside whole words.
"""
READS = ()

# Values for individual E-family glyphs, not arbitrary vocabulary entries.
GLYPHS = {
    'ε': 4.7, 'έ': 7.1, 'Ε': 6.4, 'Έ': 5.0,
    'ἐ': 2.5, 'ἔ': 3.6, 'ἑ': 0.7, 'Ἑ': 0.5, 'ὲ': 4.2,
    'E': 0.74, 'e': 0.21, 'é': 0.24, 'É': 0.51,
    'è': 2.3, 'È': 3.0, 'ê': 0.78, 'Ê': 1.65,
    'ë': 0.71, 'ě': 0.63, 'ę': 0.35, 'ė': 0.65,
    'е': 0.21, 'Е': 0.95, 'ё': 0.56, 'є': 0.78, 'Є': 1.45,
    'ɛ': 1.15, 'ϵ': 1.9, 'え': 0.6, 'エ': 0.62, '에': 0.94,
    'ֵ': 6.85, 'ֶ': 2.5, 'ְ': 1.9,
}
# Completing a character's final byte can have a different response.
SPLIT_GLYPHS = {
    'έ': 6.73, 'Ε': 7.05, 'Έ': 6.74,
    'є': 4.76, 'Є': 2.91, 'ë': 1.78,
}
DELIMITERS = " \t\r\n_./-:,'\"([{=+*>\\"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    core = s.lstrip(DELIMITERS)
    split = s == '\ufffd'
    if split:
        # Do not complete a character using bytes from another document.
        same_doc = (len(prefix.document_ids) > 1 and
                    prefix.document_ids[-1] == prefix.document_ids[-2])
        if not same_doc:
            return None, 0.0
        core = prefix.text_prefixes[-1][-1:]
    value = GLYPHS.get(core, 0.0)
    if split:
        value = SPLIT_GLYPHS.get(core, value)
    elif s[:1].isspace():
        if core == 'ε':
            value = 3.86
        elif core in ('E', 'É'):
            value += 0.18
        elif core in ('è', 'È'):
            value *= 0.57
        elif core == 'é':
            value = 0.485
        elif core == 'е':
            value = 0.75
        elif core == 'Е':
            value = 1.1
        elif core == 'e':
            value = 0.29
    elif core == 'e' and s != core:
        value = 0.36 if s.startswith('.') else 0.65
    elif core == 'E' and s != core:
        value = 0.95
    if core.lower() == 'epsilon':
        value = 2.15 if s.startswith('.') else 1.25
    elif core == 'psilon':
        value = 1.05
    return None, float(value)

programs.haiku:
"""The letter E in its many forms, by how strongly it drives this component:
Greek epsilon (ε, έ, Ε) is by far the strongest, then è, then capital E,
Greek delta, other accented e's, and plain e last."""
import unicodedata

READS = ()


def value(token):
    s = token.strip()
    if len(s) != 1:
        return 0.0
    name = unicodedata.name(s, "")
    if "EPSILON" in name:
        return 7.0 if "TONOS" in name else 4.5
    if "DELTA" in name:
        return 0.8
    base = unicodedata.normalize("NFD", s)[0]
    if base == "E":
        return 0.8 if s == "E" else 0.6
    if base == "e":
        if s == "e":
            return 0.25
        if "GRAVE" in name:
            return 2.3
        return 0.3 if s == "é" else 0.7
    if "CYRILLIC" in name and "IE" in name:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    return None, value(prefix.token_strings[-1])

programs.luna:
"""A sparse lexical proxy for rare group-care and training terms.

The harvest's only high-importance examples were 慰问 (visiting to show care)
and 军训 (military training). Give those terms their observed negative pulses;
use the component's tiny mean elsewhere. This does not infer a broader topic.
"""
READS = ()

BASELINE = 0.000591
GROUP_CARE_OR_TRAINING = {
    "慰问": -0.7627,
    "军训": -0.7295,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    return None, GROUP_CARE_OR_TRAINING.get(word, BASELINE)

"""A sparse lexical/syntactic estimate: auxiliary tokens after pronouns
are positive; “to” and ease/difficulty words are negative, especially
“easy/difficult to”. Most other tokens are predicted as zero.
"""

READS = ()

AUXILIARIES = {
    "am", "is", "are", "was", "were", "be", "been", "being",
    "do", "does", "did", "have", "has", "had",
    "can", "could", "will", "would", "shall", "should",
    "may", "might", "must", "'s", "’s", "'ve", "’ve",
}
SUBJECT_PRONOUNS = {"i", "you", "he", "she", "it", "we", "they"}
EASE_OR_DIFFICULTY = {
    "easy", "easier", "easiest", "hard", "harder", "hardest",
    "difficult", "difficulty", "simple", "simpler", "impossible",
    "worth",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = prefix.token_strings[-2].strip().lower() if same_document else ""

    if word == "to":
        return None, -2.0 if previous in {"easy", "difficult"} else -0.26
    if word in EASE_OR_DIFFICULTY:
        return None, -1.0
    if word in AUXILIARIES and previous in SUBJECT_PRONOUNS:
        return None, 0.36
    return None, 0.0

programs.sol:
"""A spelling detector for short consonant-cluster syllables.

It mostly predicts negative contributions on little chunks such as bre, clo,
fro and gre, rather than on complete longer words. A consonant cluster plus a
vowel is scored by its onset, vowel, capitalization and leading space.
Selected Cyrillic and katakana spellings use the same approximate rule.
Consonant-only chunks and liquid-plus-vowel chunks have weaker responses.
A few common short words and document-format markers are handled separately.
No previous tokens or upstream components are used.
"""
import re
import unicodedata

READS = ()
CYRILLIC = str.maketrans({
    'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'з': 'z', 'к': 'k',
    'л': 'l', 'м': 'm', 'н': 'n', 'п': 'p', 'р': 'r', 'с': 's',
    'т': 't', 'ф': 'f', 'х': 'h', 'ч': 'ch', 'ш': 'sh', 'ы': 'i',
    'э': 'e', 'ю': 'u', 'я': 'a', 'а': 'a', 'е': 'e', 'и': 'i',
    'о': 'o', 'у': 'u',
})
# Onsets are ordinary consonant clusters, not vocabulary token identifiers.
ONSET = {
    'bl': -0.55, 'br': -0.95, 'cl': -0.8, 'cr': -0.75,
    'dr': -0.6, 'fl': -0.55, 'fr': -0.55, 'gl': -0.6,
    'gr': -0.8, 'kl': -0.75, 'kr': -0.9, 'pl': -0.4,
    'pr': -0.35, 'sl': -0.7, 'sm': -0.6, 'sn': -0.85,
    'sp': -0.55, 'st': -0.35, 'sw': -0.75, 'tr': -0.45,
    'vr': -0.7, 'sk': -0.45, 'str': -0.7, 'spr': -0.6,
    'scr': -0.65, 'schl': -0.6, 'schr': -0.65, 'schw': -0.55,
    'thr': -0.5, 'zw': -0.65, 'kn': -0.7,
}
VOWEL = {'a': -0.05, 'e': 0.0, 'i': 0.05,
         'o': -0.2, 'u': -0.05, 'y': 0.1}
L_VOWEL = {'a': 0.0, 'e': -0.45, 'i': 0.05,
           'o': -0.75, 'u': 0.2, 'y': -0.2}
COMMON_SHORT_WORDS = {'the', 'she', 'who', 'why', 'try', 'sky', 'two',
                  'что', 'для', 'где', 'кто', 'мне', 'все', 'три'}
KATAKANA = {'ク': 'k', 'グ': 'g', 'ブ': 'b', 'プ': 'p',
            'フ': 'f', 'ト': 't', 'ド': 'd', 'ス': 's'}
KATAKANA_R = {'ラ': 'a', 'リ': 'i', 'ル': 'u', 'レ': 'e', 'ロ': 'o'}
MARKERS = {'<tool_response>': 0.37, '</think>': -0.29,
           '<|endoftext|>': -0.035}


def syllable(onset, vowel, capital, space, lower, cyrillic):
    value = ONSET[onset] + VOWEL[vowel[0]]
    if onset.endswith('l'):
        value += L_VOWEL[vowel[0]] - 0.15 * capital
    if space:
        value -= 0.05
        if lower and onset in {'pr', 'fr', 'br', 'tr'}:
            value += 0.15 if onset == 'pr' else 0.05
    if len(vowel) > 1:
        value += 0.5
    if cyrillic and onset.startswith('s'):
        value += 0.1
    if onset == 'str' and vowel == 'a':
        value += -0.6 if capital else 0.3
    if onset == 'fl' and vowel == 'e':
        value -= 0.45
    if onset == 'cl':
        value += {'a': -0.35, 'e': 0.2}.get(vowel, 0.0)
    if onset == 'pr' and vowel == 'i' and not cyrillic:
        value -= 0.3
    if onset == 'br' and vowel == 'o':
        value += 0.3 if space and lower else -0.25 if capital else 0.0
    return min(value, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MARKERS:
        return None, MARKERS[token]
    letters = ''.join(c for c in token if c.isalpha())
    if letters.lower() in COMMON_SHORT_WORDS:
        return None, 0.0
    cyrillic = any('\u0400' <= c <= '\u04ff' for c in letters)
    s = letters.lower().translate(CYRILLIC)
    s = ''.join(c for c in unicodedata.normalize('NFD', s)
                if not unicodedata.combining(c))
    capital, space = letters.istitle(), token.startswith(' ')
    lower = letters.islower()
    if s in {'dry', 'gli'}:
        return None, -0.1 if s == 'dry' else -0.25
    if len(s) == 2 and s[0] in 'rl' and s[1] in 'aeiouy':
        value = (-0.2 if s == 'lo' else
                 -0.08 if s in {'ra', 'ri', 'ro'} else 0.0)
        if s == 're' and lower and not space:
            value = -0.15
        return None, value
    if len(letters) == 2 and letters[0] in KATAKANA:
        if letters[1] in KATAKANA_R:
            onset = KATAKANA[letters[0]] + 'r'
            vowel = KATAKANA_R[letters[1]]
            if onset in ONSET:
                value = syllable(
                    onset, vowel, False, False, False, False
                ) - 0.25
                if vowel == 'u':
                    value *= 0.25
                elif onset[0] in 'td':
                    value *= 0.3
                return None, value
    # One vowel-initial prefix is allowed; it weakens the response.
    m = re.fullmatch(
        r'([aeiou]?)([bcdfghjklmnpqrstvwxyz]+)([aeiouy]{1,2})', s
    )
    if m and m[2] in ONSET:
        value = syllable(m[2], m[3], capital, space, lower, cyrillic)
        if m[1]:
            value *= 0.05 if s.startswith(('able', 'ible')) else 0.35
        return None, value
    if s in ONSET:
        if cyrillic and s.endswith('l'):
            return None, -0.6
        if s.startswith('s') and len(s) > 2:
            return None, -0.14 if s == 'str' else -0.45
        value = {'bl': -0.25, 'kl': -0.33, 'cl': -0.12, 'fr': -0.13,
                 'kr': -0.27, 'tr': 0.14, 'dr': 0.15, 'br': -0.05}.get(s, 0.0)
        return None, 0.04 if space and s in {'cl', 'br', 'pl'} else value
    return None, 0.0

"""A lexical 'very' detector, with weaker multilingual degree intensifiers.

This is not a general measure of emphasis: even synonymous English adverbs
can have small or negative responses. Capitalization and word-boundary
spacing change 'very'. A Chinese intensifier merged with its adjective is
weaker than an adverb standing alone or ending a token. Other tokens are zero.
"""
READS = ()

# Ordinary translations of 'very' and closely related degree adverbs.
DEGREE_WORDS = {
    'très': 0.82,       # French
    'sehr': 0.66,       # German
    'muy': 0.69,        # Spanish
    'muito': 0.41,      # Portuguese
    'molto': 0.49,      # Italian
    'очень': 0.75,      # Russian
    'rất': 0.75,        # Vietnamese
    'bardzo': 0.36,     # Polish
    'sangat': 0.38,     # Indonesian
    'mycket': 0.27,     # Swedish
    'とても': 0.53,    # Japanese
    'すごく': 0.44,
    'とっても': 0.26,
    'extremely': 0.49,
    'exceedingly': 0.28,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    if lower == 'very':
        if word == 'very':
            value = 1.40 if raw.startswith(' ') else 1.02
        elif word == 'Very':
            value = 1.33
        else:
            value = 1.22 if raw.startswith(' ') else 0.65
    elif lower in DEGREE_WORDS:
        value = DEGREE_WORDS[lower]
        if word == 'Очень':
            value = 0.51
    # 很 and 非常 mean 'very'; 非常に is the Japanese adverb form.
    elif word == '非常に':
        value = 0.54
    elif '非常' in word:
        value = 0.93 if word == '非常' else (
            0.80 if word.endswith('非常') else 0.40)
    elif '很' in word:
        if '不' in word:
            value = 0.20
        elif word == '很':
            value = 0.89
        else:
            value = 0.68 if word.endswith('很') else 0.38
    elif word in {'十分', '极', '極', '极其', '極其'}:
        value = 0.29
    elif word in {'really', 'highly', 'incredibly', 'totally'}:
        value = 0.12 if raw.startswith(' ') else 0.0
    elif lower in {'entirely', 'particularly', 'significantly'}:
        value = -0.13
    else:
        value = 0.0
    return None, value

"""Approximate a negative detector for written be- fragments.

Its largest peaks are bed (especially the bed in testbed), between, behind
and bet. Short bel/beh/ben fragments and belief/behavior/belonging words
are weaker peaks; common grammatical be- words are excluded. Case and word
boundaries affect the strength. Between is stronger after distance words
and weaker after contrast words. A few bed/between translations and the
Japanese/Korean be syllables receive similar negative predictions.
Everything else is predicted as zero; fine lexical/contextual variation
outside these families is deliberately omitted.
"""

READS = ()

# Common be- words that are not strong peaks of this detector.
NO_PEAK = frozenset('''
be been being before because become becomes became becoming below
better best begin begins began beginning benefit benefits beneficial
beautiful beauty behalf
'''.split())


def response(token, previous, start):
    word = token.strip().lstrip('_-/.')
    lower = word.lower()
    boundary = token[:1].isspace() or token[:1] in '_-/.'

    if lower == 'bed':
        if word.isupper():
            return -2.8
        if token == 'bed':
            if previous.endswith('test'):
                return -7.75 if '/' in previous else -6.85
            return -5.25 if start else -3.0
        return -4.1 if boundary else -3.7

    if lower == 'between':
        preceding = previous.strip().lower()
        if preceding in ('distance', 'distances', 'spacing'):
            return -4.0
        if preceding in ('difference', 'differences', 'distinguish'):
            return -2.2
        if word.isupper():
            return -2.6
        return -3.3 if word.istitle() else -2.9
    if lower == 'behind':
        return -3.3 if word.istitle() else -2.9
    if lower == 'bet':
        if word.isupper():
            return -1.5
        return -2.95 if boundary and word.islower() else -2.4

    if lower.startswith('be'):
        if lower in NO_PEAK:
            if word == 'BE':
                return -0.7
            return -0.2 if not boundary or word.istitle() else 0.0
        if lower == 'beds':
            return -2.8
        if lower == 'beh':
            return -2.3 if boundary else -2.9
        if lower == 'bew':
            return -2.7 if word.islower() else -1.8
        if lower == 'bel':
            return -2.3 if boundary else -1.6
        if lower == 'ben':
            return -1.8 if boundary else -1.2
        if lower in ('beg', 'bef', 'bes', 'bem', 'ber'):
            return -1.2 if boundary else -0.6
        if lower.startswith(('belong', 'belief', 'belie', 'behav', 'betr')):
            return -0.5 if lower.startswith('believ') else -1.3
        if lower.startswith(('bed', 'bett')) or lower in ('bets', 'beneath'):
            return -1.5
        return -0.5

    # Semantic counterparts of bed and between, plus written be syllables.
    if word == '床':
        return -4.7
    if word.startswith('床'):
        return -2.8
    if lower in ('между', 'بين'):
        return -2.1
    if lower in ('zwischen', '之间的', '之間'):
        return -1.3
    if lower in ('entre', '之间'):
        return -0.9
    if word in ('ベ', '베'):
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    start = len(docs) == 1 or docs[-1] != docs[-2]
    previous = '' if start else prefix.token_strings[-2]
    return None, response(prefix.token_strings[-1], previous, start)

