"""Recognize strong 'be' tokens, distinguishing a bed from the suffix in scrubbed."""
READS = ()
STRONG = {
    "between": -3.1,
    "behind": -3.0,
    "bet": -3.0,
}
def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "bed":
        previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
        if previous == "test":
