programs.sol:
"""A selective lexical signal for position, placement, and orientation.

Position/pos and the related pos/pose/posit spellings get the largest values.
Location, arrangement, and functional 'place' words get smaller positives.
Certain containment/cardinal terms get negatives. A few East Asian
placement words and characters are included. One-token memory distinguishes phrasal
idioms and split words; it also carries a weak position signal onto 'of'.
Unrecognized tokens predict zero; this is not a general spatial reasoner.
"""
import re
from functools import lru_cache

READS = ()

LOCATION = frozenset('location locations forward upward downward situated'.split())
POSITION_OR_STATE = frozenset('''status opposite reverse inverse
    orientation orientations'''.split())
PLACEMENT = frozenset('''place places placed placing located seat sitting
    seated clockwise backward'''.split())
ARRANGEMENT = frozenset('''direction directions spatial horizontal vertical
    perpendicular shape shapes size sizes around round arrangement arranged
    post posts posted sit stand standing station reach reached reaching'''.split())
FUNCTIONAL_PLACE = frozenset('''process processes role roles potential presence
    workspace directory repo repository website websites progress format
    employment occupation employed capacity situation situations'''.split())
PLACE_ACTIONS = frozenset('''put puts putting stand stands raise raised
    raising suppose'''.split())
SPATIAL_ATTRIBUTES = frozenset('''site sites layout shaped offset folder
    dir url former fore forecast dimension dimensions
    coordinates upper upon laid lie lies sat'''.split())
CONTAINMENT_AND_CARDINAL = frozenset('''back behind inside outside internal
    external center centre central among against north west south top'''.split())


@lru_cache(maxsize=32768)
def lexical(token):
    w = token.strip().strip('.,:;()[]{}<>/\\_-=+!\"\'').lower()
    if (w in ('pos', 'xpos', 'ypos', 'position')
            or re.search(r'[a-z]Position$', token)):
        return 3.85
    if w == 'positions':
        return 3.2 if token != 'positions' else 1.85
    if w in ('posi', 'posit', 'positioned', 'positioning', 'positional',
             'composition', 'compos'):
        return 2.5
    if w in ('compositions', 'osition', 'posicion', 'posición', 'poz'):
        return 2.0
    if w.startswith(('positive', 'deposit', 'depos',
                     'proposition', 'opposition')):
        return 1.75
    if w in ('pose', 'poses', 'posed', 'posing', 'poser', 'supposed',
             'disposed', 'disposition', 'compose', 'composer'):
        return 0.78 if token == 'pose' else 1.25
    if w in ('expose', 'exposed', 'exposure', 'oppose', 'opposing'):
        return 1.0
    if w in ('composed', 'propose', 'proposed', 'proposal', 'opposed'):
        return 0.8
    if w in ('impose', 'imposed', 'possess', 'possession', 'poss'):
        return 0.6
    if w == 'negative':  # The opposite polarity word also gives a signal.
        return 0.65
    # Position equivalents, and the roots of Russian place/position words.
    if w in ('位置', '的位置', '위치'):
        return 2.9
    if w in ('布置', '地理位置'):
        return 2.0
    if w in ('定位', '地位', '仓位', '岗位', '工作岗位', '位居', '姿势', '卧', '寝'):
        return 1.7
    if w in ('向前', '站在', '坐在', '摆放', '布局', '职务'):
        return 1.25
    if w in '位座坐向站職仕状倒姿跪横' and len(w) == 1:
        return 1.4
    if w in '放正置占俯竖' and len(w) == 1:
        return 1.0
    if w in '地投進逼垂铺埋摆拱举形' and len(w) == 1:
        return 0.75
    if w in ('上', '前', '東'):
        return 0.4
    if w in ('中', '内', '南', '北'):
        return -0.18
    if w.startswith(('располож', 'полож')):
        return 2.4
    if w.startswith(('мест', 'поз')):
        return 1.1
    if w == 'git' and token.startswith('.'):
        return 0.54
    if w == 'workspace' and token.startswith('/'):
        return 0.82
    for words, value in ((LOCATION, 1.35), (POSITION_OR_STATE, 1.05),
                         (PLACEMENT, 0.95), (ARRANGEMENT, 0.7),
                         (FUNCTIONAL_PLACE, 0.65), (PLACE_ACTIONS, 0.56),
                         (SPATIAL_ATTRIBUTES, 0.46), (CONTAINMENT_AND_CARDINAL, -0.23)):
        if w in words:
            return value
    return 0.0


IDIOMATIC_UP = frozenset('''set setting make made show grow grew
    clean follow'''.split())
END_UP = frozenset('end ends ended sign signed wake woke'.split())
MOTION = frozenset('go goes going walk walks travel travels jump'.split())
TAKE = frozenset('take takes took taken taking'.split())
BREAK = frozenset('shut break breaks broken breaking'.split())


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    w, prev = token.strip().lower(), previous.strip().lower()
    value = lexical(token)
    if w == 'up':
        value = 0.5
        if prev in IDIOMATIC_UP:
            value = 0.0
        elif prev in END_UP:
            value = -0.18
        elif prev in MOTION:
            value = 0.82
    elif w == 'down':
        value = 0.87
        if prev in BREAK:
            value = 0.0
        elif prev in ('sit', 'sat', 'slow', 'slowing'):
            value = 0.2
    elif w == 'place' and prev in TAKE:
        value = 0.26  # Taking place means happening.
    elif w == 'of' and lexical(previous) >= 0.8:
        value = 0.24 * lexical(previous)
    elif token == 'position':
        value = 3.6
        if prev.endswith(('pro', 'dis', 'decom')):
            value = 1.5
        elif prev.endswith(('ex', 'sup', 'inter', 'kom')):
            value = 2.1
        elif prev.endswith('com'):
            value = 2.4
    elif token == 'pos' and prev.endswith(('cuer', 'cor', 'tem', 'em', 'ty')):
        value = 1.6  # cuerpos/corpos, tiempos/tempos, typos: not placement.
    return (doc, token), value

programs.luna:
"""Recognize path separators, shell switches, and a few repository markers."""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

SHELL_WORDS = frozenset({"cd", "chmod", "exit", "git", "install", "npm"})
REPOSITORY_MARKERS = frozenset({"readme", "makefile", "make", "license"})


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous_line, listing = "", False
    else:
        previous_line, listing = carry[1], carry[2]

    before = previous_line
    current = before + token
    lower = token.lower().strip()
    slashes = token.count("/")
    piece = token.lstrip()
    dotfile = piece.startswith(".") and any(char.isalpha() for char in piece[1:]) and (
        not before or before[-1].isspace() or before.rstrip().endswith("/")
    )
    marker = lower in REPOSITORY_MARKERS or (
        before.rstrip().lower().endswith(".git") and lower.startswith("ignore")
    ) or (listing and before.rstrip().lower().endswith("make") and lower.startswith("file"))

    value = 0.0
    if slashes and "</" not in token and "://" not in token:
        value = 0.35
        if ".." in token or "${" in token:
            value = 0.6
    elif dotfile or (listing and marker):
        value = 0.35
    elif before.rstrip().endswith("/") and not before.rstrip().endswith("</"):
        value = 0.15
    elif lower in SHELL_WORDS or token.strip().startswith(("--", "$", "${")):
        value = 0.4
    elif "--" in token or "${" in token:
        value = 0.4

    lines = current.split("\n")
    ended_line = len(lines) > 1
    if ended_line:
        finished = "\n".join(lines[:-1])
        spaces = sum(1 for part in finished.split(" ") if part == "")
        listing = finished.count("/") >= 2 and spaces >= 3
        current = lines[-1]
    else:
        # A row of a repository listing often has aligned columns and one path slash.
        if current.count("/") >= 1 and "   " in current:
            listing = True
        elif "\n" not in token and listing:
            pass
    return (doc, current, listing), float(value)

programs.sol:
"""A partial lexical explanation: standards, regulation and conformity language.

Negative pulses mark standards terminology. Nearby technical qualifiers,
standards identifiers, and compliance language strengthen them. The rules
recognize English, Chinese and a Russian standard stem, plus the GB/T notation.
ASCII digits in a standards citation receive a weaker continuation pulse.
Most other tokens are zero. Document beginnings get larger negative pulses.
This omits the component's other word-specific responses.
"""
READS = ()

CODES = {'ISO', 'DIN', 'EN', 'GB', 'ASTM', 'ANSI', 'IEC', 'JIS'}
QUALIFIERS = {
    'international', 'national', 'safety', 'regulatory', 'industry',
    'industrial', 'quality', 'rigorous', 'stringent', 'certified',
    'environmental', 'technical', 'reference', 'test', 'testing',
    'legal', 'auditing',
}
CHINESE_QUALIFIERS = {
    '安全', '质量', '質量', '技术', '技術', '国家', '國家', '认证',
    '認證', '标准', '標準', '规范', '規範', '行业', '行業', '管理体系', '资质',
}
CONFORMITY = {
    'comply', 'compliance', 'conform', 'conformity', 'accordance',
    'adherence', 'approved', 'requirements', 'certification',
}

# Familiar terminology, grouped rather than learned token identities.
TERMS = {
    'standard': (-0.14, {'standard', 'standardized', 'standardization'}),
    'standards': (-0.26, {'standards'}),
    'chinese_standard': (-0.34, {'标准', '標準', '规范', '規範'}),
    'standard_sign': (-0.24, {'标', '標'}),
    'regulation': (-0.18, {'regulations', 'regulatory'}),
    'rule': (-0.12, {'regulation', 'codes', 'authority'}),
    'authorities': (-0.06, {'authorities'}),
    'chinese_rules': (-0.22, {'规定', '規定', '规程', '規程', '颁布', '頒布'}),
    'statutes': (-0.40, {'法规', '法規'}),
    'certification': (-0.14, {
        'certification', 'certifications', 'certified', '认证', '認證',
        'specification', 'specifications', '证书', '證書',
    }),
    'guidance': (-0.06, {'guideline', 'guidelines', 'handbook'}),
    'accordance': (-0.10, {'accordance'}),
    'manuals': (-0.28, {'手册', '手冊', '资质', '資質'}),
    'chinese_guidance': (-0.08, {'指导', '指導', '要求'}),
    'quality_system': (-0.55, {'管理体系', '管理體系'}),
}
LOOKUP = {w: (k, v) for k, (v, words) in TERMS.items() for w in words}

# Extra negative pulses: qualifier within 16 / within 4 / immediately before,
# standards code within 16, and a conformity word within 16 tokens.
CONTEXT = {
    'standard': (0.11, 0.03, 0.16, 0.43, 0.13),
    'standards': (0.11, 0.04, 0.20, 0.27, 0.10),
    'chinese_standard': (0.12, 0.07, 0.12, 0.10, 0.10),
    'standard_sign': (0.15, 0.00, 0.00, 0.10, 0.06),
    'standard_code': (0.10, 0.35, 0.00, 0.00, 0.18),
    'certification': (0.05, 0.06, 0.09, 0.37, 0.10),
    'annex': (0.07, 0.07, 0.02, 0.00, 0.00),
}
DEFAULT_CONTEXT = (0.06, 0.04, 0.04, 0.05, 0.08)


def response(token, previous):
    word = token.strip()
    lower = word.lower()
    if word == '/T' and previous == 'GB':
        return 'standard_code', -0.21
    if word in CODES:
        value = -0.21 if word in {'EN', 'GB'} else -0.30
        if word == 'EN' and not token[:1].isspace():
            value = -0.08
        return 'standard_code', value
    if lower == 'annex':
        return 'annex', -0.57 if word[:1].isupper() else -0.35
    if lower == 'directive':
        value = -0.30 if word[:1].isupper() and token[:1].isspace() else -0.12
        return 'regulation', value
    if lower.startswith('стандарт'):
        return 'standard', -0.25
    if word in {'国家标准', '國家標準'}:
        return 'chinese_standard', -0.68
    if word in {'标准化', '標準化', '的标准', '的標準'}:
        return 'chinese_standard', -0.28
    kind, value = LOOKUP.get(lower, (None, 0.0))
    if lower in {'standard', 'codes'} and not token[:1].isspace():
        value += 0.07
    return kind, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', (), 0.0)
    _, position, previous, history, citation = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    kind, value = response(token, previous)
    if kind is not None:
        q16 = any(h[0] for h in history)
        q4 = any(h[0] for h in history[-4:])
        q1 = bool(history and history[-1][0])
        code = any(h[1] for h in history)
        conform = any(h[2] for h in history)
        norm_mentioned = any(h[3] for h in history)
        weights = CONTEXT.get(kind, DEFAULT_CONTEXT)
        value -= sum(w * present for w, present in zip(
            weights, (q16, q4, q1, code, conform)
        ))
        if kind == 'standard_code' and norm_mentioned:
            value -= 0.20
        if position == 0:
            if kind in {'standard', 'standards', 'chinese_standard', 'standard_sign'}:
                value = -1.25 if kind != 'standards' else -1.55
            else:
                value -= 0.45
        elif position == 1 and kind == 'standard':
            value -= 0.20
    if kind == 'standard_code':
        # Continue the numeric part of an ISO, EN, GB/T, etc. designation.
        citation = value
    elif citation and word.isascii() and word.isdigit():
        value = 0.5 * citation
    elif not (word in {'', '/', '-', '.'} and '\n' not in token):
        citation = 0.0
    qualifier = word.lower() in QUALIFIERS or any(
        s in word for s in CHINESE_QUALIFIERS
    )
    norm = kind in {'standard', 'standards', 'chinese_standard', 'standard_sign'}
    flags = (qualifier, word in CODES, word.lower() in CONFORMITY, norm)
    history = (history + (flags,))[-16:]
    return (doc, position + 1, word, history, citation), float(value)

"""Recognize 'increasingly/beyond' words, especially the Chinese 越.

The bare character is strongest; complete comparative and crossing phrases
are weaker. 'export default' is negative. Tokens outside these patterns are
zero, leaving out smaller unrelated responses and byte-encoding fragments.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    word = prefix.token_strings[-1].strip()
    value = 0.0
    if word == '越':
        value = 6.1
    elif word in {'越大', '越高', '越是', '越多', '就越'}:
        value = 4.7
    elif word == '越好':
        value = 3.15
    elif word in {'越来越', '越來越'}:
        value = 3.5
    elif '越来越' in word or '越來越' in word:
        value = 2.6
    elif word == '愈':
        value = 2.8
    elif word in {'穿越', '跨越'}:
        value = 2.35
    elif word in {'跨', '逾', '越南', '日益', '日趋'}:
        value = 1.5
    elif word in {'跨境', '跨国', '跨界'}:
        value = 1.2
    elif word in {'超', '超过', '超過', '超越'}:
        value = 0.75
    elif word.startswith(('不断', '不仅')):
        value = 0.65
    elif word == 'càng':
        value = 3.4
    elif word == 'increasingly':
        value = 1.04
    elif word in {'progressively', 'coraz'}:
        value = 0.67
    elif word == 'default':
        value = -1.0 if previous == 'export' else -0.2
    return (doc, word or previous), value

programs.haiku:
"""Layer-0 MLP down_proj, component 2292: short letter fragments with a doubled letter.

What it responds to: the current token is a short, letter-only piece of text (no word
around it) that contains a doubled letter, and the doubled letter is not one of the common
English doubles ll, ss, ee, oo, ff. Examples that fire: kk, zz, gg, ww, mm, pp, tt, nn, cc,
ii, Hmm, app, itt, ott. Whole words that merely contain a double ("letter", "dollar") are
weak, and the strength falls with length: 2-letter pieces are strongest, longer pieces
barely fire. A few repeated-symbol pairs (&& || (( ++ ?? !! {{ ^^) fire at half strength.
Everything else predicts 0. The rule looks only at the current token, so it needs no state.
"""

import re

READS = ()

COMMON_DOUBLES = {"ll", "ss", "ee", "oo", "ff"}
SYMBOL_PAIRS = {"&&", "||", "((", "++", "??", "!!", "{{", "^^"}
# strength by the length (in letters) of a doubled-letter fragment
LENGTH_STRENGTH = {2: 1.4, 3: 0.8, 4: 0.5}
LONG_STRENGTH = 0.1


def strength(piece: str) -> float:
    word = piece.strip().lower()
    if word in SYMBOL_PAIRS:
        return 0.5
    if not re.fullmatch(r"[a-z]+", word):
        return 0.0
    double = re.search(r"([a-z])\1", word)
    if double is None or double.group(0) in COMMON_DOUBLES:
        return 0.0
    return LENGTH_STRENGTH.get(len(word), LONG_STRENGTH)


def step(carry, prefix, upstream):
    """This component's activation at the newest token of the prefix."""
    return None, float(strength(prefix.token_strings[-1]))

programs.sol:
"""Token-local reader address and polite speech, with an opposite end marker.

Negative signals are strongest for Chinese honorific 'you' and Japanese/Korean
polite endings; ordinary English 'you/your' is weaker. Recognizers operate on
token text, not whole sentences. Sentence particles and short honorific or
second-person endings are weaker cues. End-of-text is positive; the closing
thought marker is negative. Unrecognized tokens contribute zero.
"""
READS = ()

# Reader-address pronouns and polite self-reference. German capitals matter.
ADDRESS = {
    'you': -0.85, 'your': -1.06, 'yours': -1.5, 'yourself': -0.35,
    'vous': -2.05, '-vous': -1.9, 'votre': -2.1, 'vos': -1.3,
    'вы': -1.4, 'ваш': -2.7, 'вам': -3.1, 'вас': -2.5,
    'вашего': -1.6, 'вашей': -1.6, 'ваши': -1.3,
    'você': -1.6, 'vocês': -1.6, 'bạn': -1.6, 'tôi': -1.7, 'saya': -1.7,
    'あなた': -2.35, 'お客様': -2.6, '당신': -2.0, '여러분': -1.6,
}
GERMAN_FORMAL = {'Sie': -2.85, 'Ihnen': -4.8, 'Ihr': -1.5,
                 'Ihre': -1.9, 'Ihrem': -3.5, 'Ihrer': -2.9, 'Ihren': -2.7}

# Sentence particles and short honorific morphemes in East Asian speech.
SPEECH_MARKERS = {
    'ね': -1.5, 'よ': -0.9, 'よね': -2.6, 'か': -0.4,
    'ので': -1.15, 'なので': -0.85, 'お': -0.65, 'ご': -0.35,
    'のお': -0.95, 'にお': -0.95, 'をご': -1.3,
    '님': -1.8, '께서': -2.0, 'nhé': -2.5,
}


def token_value(token):
    w = token.strip()
    low = w.casefold()
    if w == '<|endoftext|>':
        return 1.606
    if w == '</think>':
        return -0.945
    if '您' in w:
        return -7.3 if len(w) <= 2 else -5.8
    if '你' in w and len(w) <= 4:
        return -1.3 if '们' in w or '們' in w else -0.95
    if w in ('吧', '了吧'):
        return -3.3
    if w in ('呢', '吗', '嗎', '了吗', '啦'):
        return -1.8

    # Japanese polite endings, including when a word stem shares their token.
    base, tail = w, ''
    for ending in ('ので', 'から', 'けど', 'よね', 'が', 'し', 'ね', 'よ', 'か'):
        if w.endswith(ending):
            base, tail = w[:-len(ending)], ending
            break
    value = None
    if base.endswith('です'):
        value = -6.1 if base == 'です' else -5.0
    elif base.endswith('でしょう'):
        value = -5.4
    elif base.endswith('ません'):
        value = -5.4
    elif base.endswith(('ました', 'でした')):
        value = -5.2 if not base.endswith('いました') else -4.1
        if base == 'しました':
            value = -6.3
    elif base.endswith('ます'):
        value = -5.8 if not base.endswith('ています') else -4.7
        if base in ('ます', 'します', 'います'):
            value = -6.2
    if value is not None:
        if tail in ('ので', 'から', 'けど', 'が', 'し'):
            value *= 0.6
        elif tail:
            value *= 0.83
        return value
    if w.endswith(('ください', '下さい')):
        return -4.5
    if w.endswith('ましょう'):
        return -3.7

    # Korean formal declaratives, polite questions and requests.
    if w.endswith('니다') and w != '아니다':
        if token.startswith(' '):
            return -5.0
        if w == '합니다':
            return -7.6
        if w == '입니다':
            return -6.9
        return -5.8
    if w.endswith(('세요', '십시오', '습니까', '까요', '네요', '죠')):
        return -3.8
    if w == '요':
        return -0.4 if token.startswith(' ') else -2.4
    if w.endswith(('어요', '아요', '해요', '거든요')):
        return -3.0

    if w in SPEECH_MARKERS:
        return SPEECH_MARKERS[w]
    if w.startswith('ご') and len(w) > 1:
        return -1.8
    # Russian second-person ability/want forms and imperative-ending fragments.
    if low in ('можете', 'сможете', 'хотите'):
        return -1.7
    if w in ('ите', 'айте', 'те', 'итесь', 'есь'):
        return -0.65
    if w in ('йте', 'ьте', 'йтесь'):
        return -1.2
    if w in GERMAN_FORMAL:
        return GERMAN_FORMAL[w]
    if low in ADDRESS:
        return ADDRESS[low]
    if low in ('usted', 'ustedes'):
        return -3.8 if token.startswith(' ') else -0.3
    if w == 'Anda':
        return -2.5
    return 0.0


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

