"""A spelling-based randomness detector, not a sentence-level judgment.

Literal 'random' is strongest; its derivatives and multilingual roots also
fire. Probability, arbitrary-choice and disorder vocabulary fire weakly.
Remember one token to recognize split words and 'random number' phrases,
resetting that memory at document boundaries. Everything else predicts zero.
"""
READS = ()

CHANCE_WORD_FORMS = {'randomly': 6.0, 'randomness': 4.5, 'getrandom': 5.0,
                     'andom': 5.4, 'bitrary': 2.6}
# Chinese/Japanese roots: disorder, follow/at will, and random.
# 机/機 is 'machine', also the second character of Chinese 'random'.
CHANCE_ROOTS = {'乱': 4.0, '亂': 4.0, '随': 2.6, '隨': 3.5,
                '随机': 6.2, '随便': 3.3, '随意': 2.8,
                '混乱': 1.8, '机': 0.5, '機': 0.5}
STATISTICS = {'distribution', 'distributions', 'distributed', 'independent',
              'independently', 'uniform', 'uniformly', 'noise', 'noises', 'seed'}
ARBITRARY_CHOICE = {'arbitrary', 'arbitrarily', 'stochastic', 'ochastic'}
# Disorder, free choice, independence and gambling vocabulary.
ASSOCIATED_WORDS = {'disorder', 'chaos', 'casual', 'misc', 'miscellaneous', 'noisy',
                    'unpredictable', 'unrelated', '狂', '杂', '自由', '独立',
                    '獨立', '博彩', '疯狂'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-([/=')
    lower = word.lower()
    value = CHANCE_WORD_FORMS.get(lower, CHANCE_ROOTS.get(word, 0.0))
    if lower == 'random':
        value = 8.3
        if token.startswith('.'):
            value = 8.0 if word[0].isupper() else 9.0
        elif token.startswith(('(', '[')):
            value = 5.3 if token.startswith('[') else 6.2
        elif token.startswith(('_', '=')):
            value = 7.4
    elif lower.startswith('randomiz'):
        value = 3.4
    elif lower.startswith('random') and lower not in CHANCE_WORD_FORMS:
        value = 2.8  # compound identifiers, e.g. RandomForest
    elif lower.startswith('случай'):  # Russian chance/random root
        value = 3.2
    elif lower == 'rand':
        value = 2.2 if token.startswith(('_', '.', '/')) else 1.1
    elif lower in ('rng', 'randint', 'randn'):
        value = 1.0
    elif lower in ARBITRARY_CHOICE:
        value = 1.6
    elif lower in STATISTICS:
        value = 0.7
    elif lower in ASSOCIATED_WORDS:
        value = 0.8
    if previous in ('random', 'andom'):
        if token == 'ly':
            value = 4.5
        elif token == 'ized':
            value = 2.6
        elif token in ('izing', 'ised', 'isation', 'ization'):
            value = 1.2
        elif lower in ('number', 'numbers', 'variable', 'variables',
                       'generator', 'sampling', 'selected'):
            value += 0.5
    elif previous in ('随', '隨') and word in ('机', '機'):
        value = 1.6
    elif previous == 'случай' and token in ('но', 'ный', 'ные', 'ных'):
        value = 1.7
    return (doc, lower), value

"""Mostly recognize the spelling 'in', especially at word beginnings.

Capitalized In and short inf-/inv- fragments fire strongly. Whole in- words
fire less; word-internal endings (-ing, -ine, etc.) and lexicalized families
(information, integer, individual, image) are weak. Im- and a small set of
spatial/temporal relation words fire moderately. Familiar 'result in' and
'interest in' combinations suppress the response to in, as do several
verbs/nouns taking an in-complement; clause links strengthen it.
This approximates the dominant pattern, not the many smaller responses to unrelated words.
A few in/entry spellings in other scripts and chat delimiters are included.
"""

import re

READS = ()
STRIP = ' \t\r\n([._/-\"\''
LEXICALIZED = ('information', 'información', 'информа', 'integer',
               'individual', 'image', 'important', 'improv')
RELATIONS = {'after', 'under', 'access', 'entry', 'entries'}
IN_RELATIONS = {'within', 'until', 'wherein', 'herein', 'therein', 'enter'}
IN_COMPLEMENTS = {'involved', 'included', 'embedded', 'found', 'based',
                  'engage', 'engaged', 'engaging', 'participate', 'role',
                  'part', 'published'}
CLAUSE_LINKS = {'and', 'but', 'or', 'that', 'which', 'even'}
ENTRY_WORDS = {'内', '內', '入', '入れ', '投入', '进入', '进去', '输入',
               '进', '進', '插'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    word = token.lstrip(STRIP)
    w = word.lower()
    boundary = len(word) < len(token)
    value = 0.0
    if w == 'in':
        previous = re.search(r'([A-Za-z]+)$', tail)
        previous = previous.group(1).lower() if previous else ''
        if word == 'In':
            value = 1.95
        elif token.startswith('.'):
            value = 4.0
        elif token.startswith(('/', '-', '_', '"', "'")):
            value = 2.15
        elif not boundary:
            value = 0.33 if tail[-1:].isalpha() else 1.55
            if tail.endswith('\\'):
                value = 0.95
        elif previous.startswith('result'):
            value = 0.12
        elif previous.startswith('interest'):
            value = 0.32
        elif previous in IN_COMPLEMENTS:
            value = 0.72
        elif previous in CLAUSE_LINKS:
            value = 1.60
        elif word == 'IN':
            value = 1.65
        else:
            value = 1.50 if not previous else 1.27
    elif w.startswith(LEXICALIZED):
        value = 0.13
    elif w.startswith(('info', 'init')):
        value = 1.25 if w.startswith('info') else 0.85
    elif w.startswith(('in', 'im')):
        if not boundary and w[2:].startswith(('a', 'e', 'i', 'o', 'g')):
            value = 0.08
        elif w == 'int':
            value = 0.9 if boundary else 0.75
        elif w == 'inst':
            value = 3.0 if boundary else 2.4
        elif w.startswith('infin'):
            value = 3.1
        elif w.startswith(('inner', 'inside')):
            value = 2.05
        elif w.startswith('in') and len(w) <= 4:
            if w[2] in 'fv':
                value = 3.9 if boundary else 2.7
            elif w[2] in 'csjh':
                value = 2.7 if boundary else 1.3
            elif w[2] in 'dn':
                value = 2.1 if boundary else 1.25
            else:
                value = 2.6 if w == 'intr' else 1.1
        elif w.startswith(('inv', 'infect', 'injur')) and len(w) <= 10:
            value = 1.9
        elif w.startswith('in'):
            value = 1.0
        elif w.startswith('import'):
            value = 1.2
        else:
            value = (0.4 if boundary else 0.16) if w == 'im' else 0.72
    elif w in RELATIONS:
        value = 0.77
    elif w in IN_RELATIONS:
        value = 0.56
    elif word in ENTRY_WORDS or word.startswith(('イン', '인', '입', '내')):
        value = 1.05
    elif w.startswith('ин'):
        value = 1.7 if boundary else 0.25
    else:
        value = {'<|im_start|>': 0.42, '</think>': 0.60,
                 '<think>': 0.28}.get(token, 0.0)
    return (doc, (tail + token)[-40:]), float(value)

"""A lexicalized English modality signal, using only a short grammatical frame.

'Perhaps' and 'maybe' activate directly. Modals and infinitive 'to' change
responses to common verbs and complements: have/been/see/tell tend negative,
while ability, discovery and assistance words tend positive. Negation,
auxiliaries, pronouns and adverbs may intervene, with weaker responses.
A few phrase continuations and document-initial modals get explicit values.
All tests use normalized token strings, not a full parser. This approximates
large English responses, not the many small lexical and multilingual effects.
State resets at each document boundary.
"""
READS = ()

# Each entry is (ordinary response, change in a strongly licensed frame).
VERBS = {
    'have': (-.14, -1.14), 'come': (-.21, -1.08),
    'tell': (-.43, -2.02), 'say': (0., -1.18), 'see': (.01, -.9),
    'happen': (-.3, -.72), 'lie': (-.04, -.66),
}
DISCOVERY = {
    'find': (.05, .72), 'help': (-.02, .81),
    'found': (-.03, 1.51), 'used': (.03, .7),
    'considered': (.01, 1.23), 'understood': (.27, .8),
}
CAPACITY = {
    'able': (.01, 1.99), 'want': (.09, 1.62),
    'interested': (.14, 1.61), 'wish': (.28, 1.7), 'need': (-.02, .88),
}
ADVERBS = {
    'easily': (.04, 1.54), 'possibly': (.34, 2.03),
    'probably': (.27, 1.45), 'certainly': (.18, 1.48),
    'potentially': (.22, 1.68), 'otherwise': (.16, 1.07),
    'never': (-.04, 1.13), 'always': (-.06, .92),
    'ever': (.06, .8), 'usually': (-.06, 1.), 'then': (-.03, .51),
}

# Response factors: ability, possibility, future, obligation, infinitive.
FAMILIES = (
    (VERBS, (1., .53, .56, .7, .4)),
    ({'been': (-.16, -1.46)}, (1., .9, .52, .76, .24)),
    (DISCOVERY, (1., .9, .41, .43, .21)),
    (CAPACITY, (.33, 1., .39, .36, .19)),
    (ADVERBS, (1., .92, .63, .55, .22)),
)
GOVERNORS = {}
for category, words in enumerate((
    'can could cannot', 'may might', "will would shall 'll 'd ’ll ’d",
    'must should', 'to'
)):
    for word in words.split():
        GOVERNORS[word] = category
BRIDGES = {
    'be': 1., 'have': 1., 'been': .65, 'not': .7, "'t": .7, '’t': .7,
    'also': .75, 'still': .7, 'just': .75, 'only': .7, 'even': .75,
    'never': .7, 'always': .7, 'ever': .7, 'then': .75,
    'you': .65, 'we': .6, 'i': .6, 'it': .65, 'they': .6,
    'he': .6, 'she': .6, 'someone': .6, 'anyone': .6,
}


def frame(history):
    """Find a governor across intervening grammatical words, not content words."""
    scale = 1.
    for word in reversed(history):
        if word in GOVERNORS:
            strong_to = word == 'to' and len(history) > 1 and history[-2] in {
                'possible', 'impossible', 'able', 'want', 'wish', 'hope'
            }
            return GOVERNORS[word], scale, strong_to
        if word in BRIDGES:
            scale *= BRIDGES[word]
        elif word.endswith('ly') and word.isalpha():
            scale *= .7
        else:
            break
    return 0, 0., False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else []
    previous_raw = carry[2] if history else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous = history[-1] if history else ''
    kind, scale, strong_to = frame(history)
    value = -.002
    for vocabulary, factors in FAMILIES:
        if word in vocabulary:
            base, strength = vocabulary[word]
            influence = factors[kind] + (.65 * factors[0] if strong_to else 0.)
            value = base + strength * scale * influence
            break
    if word in {'perhaps', 'maybe'}:
        value = 1.1 if word == 'perhaps' else .8
        if raw.strip()[:1].isupper():
            value *= .88
        if previous == 'or':
            value *= 1.25
    if word == 'you':
        value = {'can': .85, 'could': 1.35, 'would': .9, 'will': .5,
                 'should': .7, 'help': .29, 'hope': .36}.get(previous, -.02)
        if previous in {'can', 'could'} and previous_raw.strip()[:1].isupper():
            value += .45
    if word == 'to' and previous in {'want', 'wish', 'able', 'used', 'likely'}:
        kind, scale, _ = frame(history[:-1])
        base = {'want': .22, 'wish': .35, 'able': .16,
                'used': .03, 'likely': .28}[previous]
        value = base + .4 * scale * (.33, 1., .39, .36, .19)[kind]
    if word == 'of' and previous == 'capable':
        value = .43
    if word == 'like' and previous == 'would':
        value = .65
    if word in {'a', 'the'} and previous in {'have', 'been'}:
        value = -.17 if previous == 'have' else -.32
    if word in GOVERNORS and word != 'to' and not history:
        value = {'can': 2.1, 'could': 1.36, 'may': 1.53,
                 'will': .99, 'would': 1.02}.get(word, 1.)
    return (doc, (history + [word])[-5:], raw), float(value)

