"""Component layers.0.mlp.down_proj:2301: a detector for possibility and ability phrases.

Plain-terms reading of what it responds to:
- Hedges on their own: "perhaps" (and 也许 / 或许) push it positive, "maybe" a bit less;
  "possibly", "probably", "potentially", "certainly", "surely" are weakly positive.
- Right after a modal (can, could, might, may, will, would, should, must, shall, cannot)
  it is positive on the next word when that word is an adverb of possibility, frequency
  or manner ("could possibly", "can easily", "may never", "would usually"), on "you"
  ("can you"), or on a verb of wanting or helping ("can help", "may want", "can find").
  "possibly", "perhaps", "potentially" are the strongest.
- Right after a modal it is negative on a bare verb: strongly on "have", "see", "say",
  "come", "happen" ("could have", "can see"), mildly on verbs such as "do", "give",
  "provide", "show", and most strongly on "tell" ("can tell").
- After "modal be" it is positive on a participle or adjective of ability or use
  ("can be used", "may be found", "might be able", "can be considered").
- In "modal have been" ("could have been") the "been" is strongly negative.
- After "to", the verbs "have", "see", "say", "come", "happen" are mildly negative.
- Mildly negative on "have" and "been" elsewhere (perfect auxiliaries), and on "tell",
  "come", "happen" when they are not after a modal.
- Everything else predicts 0.

Activation is the component's contribution to the residual stream; these values are
typical sizes read off a simplified token-level pattern, not fitted coefficients.
"""

READS = ()

MODALS = {"can", "could", "might", "may", "will", "would", "should", "must", "shall", "cannot"}

# Adverbs of possibility, frequency or manner, plus "you" and verbs that take a bare verb.
AFTER_MODAL_POSITIVE = {
    "possibly", "perhaps", "potentially", "probably", "certainly", "surely", "easily",
    "usually", "typically", "normally", "otherwise", "never", "always", "often",
    "sometimes", "ever", "definitely", "hopefully", "likely", "either", "you", "want",
    "help", "find", "need", "like", "expect", "consider", "seem", "wish",
}

# The strongest of these right after a modal ("could possibly").
AFTER_MODAL_STRONG = {"possibly", "perhaps", "potentially"}

# Bare verbs after a modal that are strongly negative.
BARE_VERB_NEGATIVE = {
    "have", "see", "say", "come", "happen", "occur", "vary", "contain", "lie", "involve",
    "exist", "comprise",
}

# Bare verbs after a modal that are only mildly negative.
BARE_VERB_MILD = {
    "do", "give", "provide", "write", "show", "define", "explain", "reveal", "form",
    "conclude", "agree", "hide", "remain",
}

# Participles and adjectives of ability or use that follow "be" after a modal.
ABILITY_WORDS = {
    "used", "able", "found", "considered", "understood", "obtained", "calculated",
    "applied", "regarded", "interested", "possible", "expected", "viewed", "thought",
    "expressed", "computed", "converted", "accessed", "utilized", "treated",
    "represented", "reached", "easily", "helpful", "useful", "avoided", "willing",
    "either", "readily",
}

HEDGE_WEAK = {"possibly", "probably", "potentially", "certainly", "surely"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    docs = prefix.document_ids
    n = len(docs)
    # The two previous tokens, counted only if they are in this token's document.
    prev = ""
    if n > 1 and docs[-2] == docs[-1]:
        prev = _word(prefix.token_strings[-2])
    prev2 = ""
    if n > 2 and docs[-3] == docs[-1]:
        prev2 = _word(prefix.token_strings[-3])

    if prev in MODALS:
        if word == "tell":
            value = -2.0
        elif word in BARE_VERB_NEGATIVE:
            value = -0.9
        elif word in BARE_VERB_MILD:
            value = -0.25
        elif word in AFTER_MODAL_STRONG:
            value = 2.0
        elif word == "easily":
            value = 1.5
        elif word in AFTER_MODAL_POSITIVE:
            value = 1.0
        else:
            value = 0.0
    elif prev == "be" and prev2 in MODALS and word in ABILITY_WORDS:
        value = 1.0
    elif prev == "have" and prev2 in MODALS and word == "been":
        value = -1.2
    elif prev == "to" and word in BARE_VERB_NEGATIVE:
        value = -0.5
    elif word in ("perhaps", "也许", "或许"):
        value = 1.0
    elif word == "maybe":
        value = 0.8
    elif word in HEDGE_WEAK:
        value = 0.3
    elif word == "tell":
        value = -0.9
    elif word in ("have", "been"):
        value = -0.2
    elif word in ("come", "happen"):
        value = -0.35
    else:
        value = 0.0
    return None, float(value)

