"""Use modal/infinitive contexts for 'have' and hedge words as sparse lexical cues."""
READS = ()

HEDGES = {"may", "maybe", "perhaps"}
HAVE_CONTEXT = {
    "to", "not", "never", "may", "might", "can", "could", "would",
    "should", "must", "shall", "will", "can't", "couldn't", "won't",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in HEDGES:
        return None, 0.48
    if word == "have":
        start = max(0, prefix.position - 2)
        prior = [
            prefix.token_strings[i].strip().casefold()
            for i in range(start, prefix.position)
            if prefix.document_ids[i] == prefix.document_ids[-1]
        ]
        if prior and prior[-1] in HAVE_CONTEXT:
            return None, -0.32
        if len(prior) >= 2 and prior[-1] in {"'t", "’t"}:
            if prior[-2] in {"can", "could", "would", "should"}:
                return None, -0.32
    return None, 0.0

"""Approximate the strong negative comma response, softening it for numeric commas."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token not in {",", "，"}:
        return None, 0.0
    previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if previous and previous[-1].isdigit():
        return None, 0.1
    return None, -1.2
